window.registerCPNSQuestions({"packId": "pack_skb_prakom_220", "bucket": "SKB_PRAKOM", "questions": [{"id": "SKB-PRAKOM-0001", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Regulasi & Jabatan Fungsional Prakom", "q": "Berdasarkan PermenPANRB Nomor 32 Tahun 2020 tentang Jabatan Fungsional Pranata Komputer, kedudukan Pranata Komputer dibagi ke dalam dua kategori jenjang jabatan fungsional, yaitu...", "options": ["A. Kategori Pemula, Terampil, dan Kategori Komisaris Utama", "B. Kategori Pelaksana Dasar dan Kategori Pimpinan Tinggi Pratama", "C. Kategori Operator Teknis dan Kategori Analis Kebijakan", "D. Kategori Administrasi Umum dan Kategori Spesialis Jaringan", "E. Kategori Keterampilan (Terampil, Mahir, Penyelia) dan Kategori Keahlian (Ahli Pertama, Ahli Muda, Ahli Madya, Ahli Utama)"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "PermenPANRB 32/2020 membagi JF Prakom menjadi Kategori Keterampilan (Terampil, Mahir, Penyelia) dan Kategori Keahlian (Ahli Pertama, Muda, Madya, Utama).", "explanation": "Pembahasan Kisi-Kisi SKB Prakom (PermenPANRB No. 32/2020 & BKN): PermenPANRB 32/2020 membagi JF Prakom menjadi Kategori Keterampilan (Terampil, Mahir, Penyelia) dan Kategori Keahlian (Ahli Pertama, Muda, Madya, Utama)."}, {"id": "SKB-PRAKOM-0002", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Regulasi & Jabatan Fungsional Prakom", "q": "Menurut PermenPANRB Nomor 32 Tahun 2020, tiga unsur utama kegiatan tugas Jabatan Fungsional Pranata Komputer yang dapat dinilai angka kreditnya meliputi...", "options": ["A. Perencanaan anggaran keuangan, Audit forensik pajak, dan Penyuluhan hukum masyarakat", "B. Desain arsitektur gedung kantor, Manajemen armada kendaraan, dan Pengadaan logistik", "C. Tata kelola dan tata laksana teknologi informasi, Infrastruktur teknologi informasi, serta Sistem informasi dan multimedia", "D. Pengarsipan surat kertas, Pengetikan naskah dinas manual, dan Protokoler pimpinan", "E. Perakitan perangkat keras, Penjualan lisensi perangkat lunak, dan Pemasaran digital"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Hafalkan 3 Unsur Utama JF Prakom (Pasal 7 PermenPANRB 32/2020): 1) Tata kelola & tata laksana TI, 2) Infrastruktur TI, 3) Sistem informasi & multimedia.", "explanation": "Pembahasan Kisi-Kisi SKB Prakom (PermenPANRB No. 32/2020 & BKN): Hafalkan 3 Unsur Utama JF Prakom (Pasal 7 PermenPANRB 32/2020): 1) Tata kelola & tata laksana TI, 2) Infrastruktur TI, 3) Sistem informasi & multimedia."}, {"id": "SKB-PRAKOM-0003", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Tata Kelola TI & SPBE", "q": "Berdasarkan Peraturan Presiden Nomor 95 Tahun 2018 tentang Sistem Pemerintahan Berbasis Elektronik (SPBE), empat domain dalam Arsitektur SPBE Nasional yang wajib diselaraskan adalah...", "options": ["A. Arsitektur Proses Bisnis, Arsitektur Data dan Informasi, Arsitektur Aplikasi SPBE, Arsitektur Infrastruktur SPBE, Arsitektur Layanan SPBE, dan Arsitektur Keamanan SPBE", "B. Arsitektur Sosial Media, Arsitektur Periklanan, Arsitektur E-Commerce, dan Arsitektur Perbankan", "C. Arsitektur Perangkat Keras, Arsitektur Kabel Serat Optik, Arsitektur Gedung Server, dan Arsitektur Listrik", "D. Arsitektur SDM, Arsitektur Gaji, Arsitektur Cuti, dan Arsitektur Pensiun", "E. Arsitektur Jaringan Lokal, Arsitektur Komputer Desktop, Arsitektur Printer, dan Arsitektur Scanner"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Dalam Perpres 95/2018 tentang SPBE, kerangka Arsitektur SPBE mencakup 6 domain terintegrasi: Proses Bisnis, Data & Informasi, Layanan, Aplikasi, Infrastruktur, dan Keamanan SPBE.", "explanation": "Pembahasan Kisi-Kisi SKB Prakom (PermenPANRB No. 32/2020 & BKN): Dalam Perpres 95/2018 tentang SPBE, kerangka Arsitektur SPBE mencakup 6 domain terintegrasi: Proses Bisnis, Data & Informasi, Layanan, Aplikasi, Infrastruktur, dan Keamanan SPBE."}, {"id": "SKB-PRAKOM-0004", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Tata Kelola TI & COBIT 2019", "q": "Dalam kerangka kerja tata kelola TI COBIT 2019 (ISACA), terdapat pemisahan tegas antara Governance (Tata Kelola) dan Management (Manajemen). Domain yang termasuk ke dalam area GOVERNANCE (Tata Kelola) adalah...", "options": ["A. EDM (Evaluate, Direct, and Monitor)", "B. MEA (Monitor, Evaluate, and Assess)", "C. DSS (Deliver, Service, and Support)", "D. BAI (Build, Acquire, and Implement)", "E. APO (Align, Plan, and Organize)"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Trik Cepat COBIT 2019: Governance hanya 1 domain yaitu EDM (Evaluate, Direct, Monitor)! Sedangkan 4 domain lainnya (APO, BAI, DSS, MEA) adalah area Management.", "explanation": "Pembahasan Kisi-Kisi SKB Prakom (PermenPANRB No. 32/2020 & BKN): Trik Cepat COBIT 2019: Governance hanya 1 domain yaitu EDM (Evaluate, Direct, Monitor)! Sedangkan 4 domain lainnya (APO, BAI, DSS, MEA) adalah area Management."}, {"id": "SKB-PRAKOM-0005", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Manajemen Layanan TI (ITIL v4)", "q": "Dalam manajemen layanan TI berbasis ITIL (IT Infrastructure Library), proses yang bertujuan memulihkan operasional layanan normal secepat mungkin (restore normal service operation as quickly as possible) dan meminimalkan dampak buruk pada bisnis saat terjadi gangguan disebut...", "options": ["A. Service Level Management (Manajemen Tingkat Layanan)", "B. Problem Management (Manajemen Masalah)", "C. Change Enablement (Manajemen Perubahan)", "D. Release Management (Manajemen Rilis)", "E. Incident Management (Manajemen Insiden)"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Bedakan Incident vs Problem di ITIL! Incident Management = pulihkan layanan secepat mungkin (workaround/recovery). Problem Management = cari akar masalah (root cause analysis / RCA) agar tidak terulang.", "explanation": "Pembahasan Kisi-Kisi SKB Prakom (PermenPANRB No. 32/2020 & BKN): Bedakan Incident vs Problem di ITIL! Incident Management = pulihkan layanan secepat mungkin (workaround/recovery). Problem Management = cari akar masalah (root cause analysis / RCA) agar tidak terulang."}, {"id": "SKB-PRAKOM-0006", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Manajemen Layanan TI (ITIL v4)", "q": "Dokumen kesepakatan resmi antara penyedia layanan TI (IT Service Provider) dan pengguna/pelanggan internal maupun eksternal yang mendefinisikan target tingkat ketersediaan layanan (misal uptime 99,9%) dan waktu respons disebut...", "options": ["A. SLA (Service Level Agreement)", "B. OLA (Operational Level Agreement)", "C. UC (Underpinning Contract)", "D. SOP (Standard Operating Procedure)", "E. TOR (Terms of Reference)"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "SLA = Penyedia TI dengan Pelanggan/User. OLA = Kesepakatan antar-tim internal TI. UC = Kontrak dengan vendor pihak ketiga.", "explanation": "Pembahasan Kisi-Kisi SKB Prakom (PermenPANRB No. 32/2020 & BKN): SLA = Penyedia TI dengan Pelanggan/User. OLA = Kesepakatan antar-tim internal TI. UC = Kontrak dengan vendor pihak ketiga."}, {"id": "SKB-PRAKOM-0007", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Sistem Basis Data & SQL", "q": "Dalam perancangan basis data relasional, suatu tabel dikatakan telah memenuhi bentuk Normal Ketiga (3NF / Third Normal Form) apabila tabel tersebut telah berada dalam bentuk 2NF dan...", "options": ["A. Tidak memiliki ketergantungan transitif (no transitive dependency), yaitu atribut non-kunci tidak bergantung pada atribut non-kunci lainnya", "B. Masih mengizinkan adanya atribut bernilai ganda (multivalued attribute) dalam satu sel", "C. Seluruh kolom di dalam tabel tersebut bertipe data teks (VARCHAR)", "D. Memiliki ketergantungan fungsional parsial terhadap sebagian primary key komposit", "E. Tabel tersebut tidak memiliki Primary Key maupun Foreign Key sama sekali"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Hafalkan Normalisasi Basis Data: 1NF = nilai atomik (tidak ada repeating group); 2NF = lolos 1NF + hilangkan ketergantungan parsial; 3NF = lolos 2NF + hilangkan ketergantungan transitif!", "explanation": "Pembahasan Kisi-Kisi SKB Prakom (PermenPANRB No. 32/2020 & BKN): Hafalkan Normalisasi Basis Data: 1NF = nilai atomik (tidak ada repeating group); 2NF = lolos 1NF + hilangkan ketergantungan parsial; 3NF = lolos 2NF + hilangkan ketergantungan transitif!"}, {"id": "SKB-PRAKOM-0008", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Sistem Basis Data & SQL", "q": "Perhatikan perintah SQL berikut: `GRANT SELECT, INSERT ON pegawai TO staf_admin;` dan `REVOKE INSERT ON pegawai FROM staf_admin;`. Kedua perintah SQL tersebut termasuk ke dalam sub-bahasa...", "options": ["A. DML (Data Manipulation Language)", "B. DQL (Data Query Language)", "C. DDL (Data Definition Language)", "D. DCL (Data Control Language)", "E. TCL (Transaction Control Language)"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Klasifikasi SQL: DDL = CREATE, ALTER, DROP, TRUNCATE. DML = INSERT, UPDATE, DELETE. DQL = SELECT. DCL = GRANT, REVOKE. TCL = COMMIT, ROLLBACK, SAVEPOINT.", "explanation": "Pembahasan Kisi-Kisi SKB Prakom (PermenPANRB No. 32/2020 & BKN): Klasifikasi SQL: DDL = CREATE, ALTER, DROP, TRUNCATE. DML = INSERT, UPDATE, DELETE. DQL = SELECT. DCL = GRANT, REVOKE. TCL = COMMIT, ROLLBACK, SAVEPOINT."}, {"id": "SKB-PRAKOM-0009", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Sistem Basis Data & SQL", "q": "Empat sifat utama transaksi basis data yang menjamin keandalan data meskipun terjadi kegagalan sistem dikenal dengan akronim ACID. Arti huruf 'A' (Atomicity) pada prinsip ACID adalah...", "options": ["A. Data yang telah di-commit akan tersimpan secara permanen di media penyimpanan sekunder", "B. Seluruh rangkaian operasi dalam satu transaksi harus berhasil dieksekusi semuanya secara utuh (all) atau dibatalkan seluruhnya (nothing) jika salah satu gagal", "C. Basis data selalu tersedia selama 24 jam tanpa jeda pemeliharaan", "D. Transaksi yang berjalan bersamaan tidak boleh saling menginterferensi satu sama lain", "E. Setiap tabel wajib memiliki indeks pencarian otomatis"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Prinsip ACID: Atomicity (All or Nothing), Consistency (menjaga aturan integritas), Isolation (transaksi konkuren terisolasi), Durability (tersimpan permanen setelah commit).", "explanation": "Pembahasan Kisi-Kisi SKB Prakom (PermenPANRB No. 32/2020 & BKN): Prinsip ACID: Atomicity (All or Nothing), Consistency (menjaga aturan integritas), Isolation (transaksi konkuren terisolasi), Durability (tersimpan permanen setelah commit)."}, {"id": "SKB-PRAKOM-0010", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Sistem Basis Data & SQL", "q": "Seorang Pranata Komputer ingin menampilkan daftar seluruh pegawai dari tabel `pegawai` (kiri) meskipun pegawai tersebut belum memiliki catatan proyek di tabel `proyek` (kanan). Jenis operasi penggabungan tabel SQL yang paling tepat digunakan adalah...", "options": ["A. RIGHT OUTER JOIN", "B. LEFT OUTER JOIN (atau LEFT JOIN)", "C. CROSS JOIN", "D. NATURAL INNER JOIN", "E. INNER JOIN"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "LEFT JOIN menampilkan seluruh baris dari tabel sebelah kiri (`pegawai`) beserta pasangan yang cocok dari tabel kanan (`proyek`), dan mengisi NULL jika belum ada proyek.", "explanation": "Pembahasan Kisi-Kisi SKB Prakom (PermenPANRB No. 32/2020 & BKN): LEFT JOIN menampilkan seluruh baris dari tabel sebelah kiri (`pegawai`) beserta pasangan yang cocok dari tabel kanan (`proyek`), dan mengisi NULL jika belum ada proyek."}, {"id": "SKB-PRAKOM-0011", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Keamanan Siber", "q": "Sebuah sub-jaringan kantor menggunakan pengalamatan IPv4 dengan prefix `/26` (subnet mask `255.255.255.192`). Berapakah jumlah alamat IP host yang valid (usable hosts) yang dapat digunakan oleh perangkat komputer pada satu subnet tersebut?", "options": ["A. 64 host", "B. 30 host", "C. 62 host", "D. 254 host", "E. 126 host"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Rumus Usable Host Subnetting IPv4: 2^(32 - prefix) - 2 (dikurangi 2 untuk Network Address & Broadcast Address). Untuk /26: 2^(32-26) - 2 = 2^6 - 2 = 64 - 2 = 62 host!", "explanation": "Pembahasan Kisi-Kisi SKB Prakom (PermenPANRB No. 32/2020 & BKN): Rumus Usable Host Subnetting IPv4: 2^(32 - prefix) - 2 (dikurangi 2 untuk Network Address & Broadcast Address). Untuk /26: 2^(32-26) - 2 = 2^6 - 2 = 64 - 2 = 62 host!"}, {"id": "SKB-PRAKOM-0012", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Keamanan Siber", "q": "Dalam model referensi OSI 7 Layer, perangkat Router yang bekerja meneruskan paket data berdasarkan alamat logis IP (Internet Protocol) serta menentukan jalur terbaik (routing) beroperasi pada lapisan...", "options": ["A. Layer 3 — Network Layer", "B. Layer 4 — Transport Layer", "C. Layer 7 — Application Layer", "D. Layer 1 — Physical Layer", "E. Layer 2 — Data Link Layer"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Pemetaan perangkat OSI: Layer 1 (Physical) = Hub, Repeater, Kabel; Layer 2 (Data Link / MAC Address) = Switch, Bridge; Layer 3 (Network / IP Address) = Router.", "explanation": "Pembahasan Kisi-Kisi SKB Prakom (PermenPANRB No. 32/2020 & BKN): Pemetaan perangkat OSI: Layer 1 (Physical) = Hub, Repeater, Kabel; Layer 2 (Data Link / MAC Address) = Switch, Bridge; Layer 3 (Network / IP Address) = Router."}, {"id": "SKB-PRAKOM-0013", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Keamanan Siber", "q": "Serangan keamanan aplikasi web di mana penyerang menyisipkan potongan perintah kueri berbahaya ke dalam kolom input formulir login (misalnya `' OR '1'='1`) karena aplikasi tidak menerapkan prepared statements/parameterized queries disebut...", "options": ["A. Phishing Social Engineering", "B. SQL Injection (SQLi)", "C. Cross-Site Scripting (XSS)", "D. Distributed Denial of Service (DDoS)", "E. Man-in-the-Middle (MitM) ARP Spoofing"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Input `' OR '1'='1` untuk memanipulasi kueri database adalah ciri khas serangan SQL Injection. Solusi utamanya: Gunakan Prepared Statements / Parameterized Queries!", "explanation": "Pembahasan Kisi-Kisi SKB Prakom (PermenPANRB No. 32/2020 & BKN): Input `' OR '1'='1` untuk memanipulasi kueri database adalah ciri khas serangan SQL Injection. Solusi utamanya: Gunakan Prepared Statements / Parameterized Queries!"}, {"id": "SKB-PRAKOM-0014", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Keamanan Siber", "q": "Dalam penerapan Tanda Tangan Elektronik (TTE) tersertifikasi BSrE BSSN yang menggunakan kriptografi kunci publik (asimetris), proses penandatanganan dokumen digital dilakukan menggunakan..., sedangkan proses verifikasi keaslian tanda tangan oleh penerima dilakukan menggunakan...", "options": ["A. Kunci Publik milik penanda tangan ; Kunci Privat milik penerima", "B. Kunci Privat (Private Key) milik penanda tangan ; Kunci Publik (Public Key) milik penanda tangan", "C. Kunci Simetris AES yang sama untuk menandatangani dan memverifikasi", "D. Fungsi Hash MD5 tanpa kunci kriptografi", "E. Alamat MAC perangkat komputer penanda tangan"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Ingat kebalikan Enkripsi vs Digital Signature! Untuk Enkripsi Rahasia: enkripsi pakai Public Key penerima, dekripsi pakai Private Key penerima. Untuk Tanda Tangan Digital (TTE): tanda tangan pakai PRIVATE KEY pengirim, verifikasi pakai PUBLIC KEY pengirim!", "explanation": "Pembahasan Kisi-Kisi SKB Prakom (PermenPANRB No. 32/2020 & BKN): Ingat kebalikan Enkripsi vs Digital Signature! Untuk Enkripsi Rahasia: enkripsi pakai Public Key penerima, dekripsi pakai Private Key penerima. Untuk Tanda Tangan Digital (TTE): tanda tangan pakai PRIVATE KEY pengirim, verifikasi pakai PUBLIC KEY pengirim!"}, {"id": "SKB-PRAKOM-0015", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & SDLC", "q": "Dalam pengembangan perangkat lunak menggunakan kerangka kerja Agile Scrum, pertemuan singkat harian (maksimal 15 menit) yang dilakukan oleh tim pengembang untuk menyinkronkan aktivitas dan mengidentifikasi hambatan kerja disebut...", "options": ["A. Backlog Grooming", "B. Sprint Planning", "C. Sprint Retrospective", "D. Daily Scrum (Daily Stand-up Meeting)", "E. Sprint Review"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "4 Acara Resmi dalam Scrum: 1) Sprint Planning (awal sprint), 2) Daily Scrum (harian 15 menit), 3) Sprint Review (demo hasil increment di akhir sprint), 4) Sprint Retrospective (evaluasi cara kerja tim).", "explanation": "Pembahasan Kisi-Kisi SKB Prakom (PermenPANRB No. 32/2020 & BKN): 4 Acara Resmi dalam Scrum: 1) Sprint Planning (awal sprint), 2) Daily Scrum (harian 15 menit), 3) Sprint Review (demo hasil increment di akhir sprint), 4) Sprint Retrospective (evaluasi cara kerja tim)."}, {"id": "SKB-PRAKOM-0016", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & UML", "q": "Dalam pemodelan sistem berorientasi objek menggunakan Unified Modeling Language (UML), diagram yang berfungsi menggambarkan interaksi antar-objek yang disusun berdasarkan urutan waktu pengiriman pesan (message sequence over time) adalah...", "options": ["A. Use Case Diagram", "B. Deployment Diagram", "C. Sequence Diagram", "D. Component Diagram", "E. Class Diagram"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Sequence Diagram = interaksi objek berdasarkan urutan waktu (lifeline & message). Use Case = fungsionalitas sistem & aktor. Class Diagram = struktur statis kelas & relasi.", "explanation": "Pembahasan Kisi-Kisi SKB Prakom (PermenPANRB No. 32/2020 & BKN): Sequence Diagram = interaksi objek berdasarkan urutan waktu (lifeline & message). Use Case = fungsionalitas sistem & aktor. Class Diagram = struktur statis kelas & relasi."}, {"id": "SKB-PRAKOM-0017", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Pengujian", "q": "Metode pengujian perangkat lunak yang menguji fungsionalitas masukan (input) dan keluaran (output) aplikasi berdasarkan spesifikasi kebutuhan pengguna tanpa melihat struktur kode program internalnya disebut...", "options": ["A. Static Code Analysis", "B. White-Box Testing (Glass-Box Testing)", "C. Black-Box Testing", "D. Memory Leak Profiling", "E. Unit Coverage Cyclomatic Complexity Testing"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Black-Box Testing fokus pada fungsionalitas input-output tanpa melihat kode sumber internal (contoh: Equivalence Partitioning, Boundary Value Analysis). White-Box fokus pada alur logika kode internal.", "explanation": "Pembahasan Kisi-Kisi SKB Prakom (PermenPANRB No. 32/2020 & BKN): Black-Box Testing fokus pada fungsionalitas input-output tanpa melihat kode sumber internal (contoh: Equivalence Partitioning, Boundary Value Analysis). White-Box fokus pada alur logika kode internal."}, {"id": "SKB-PRAKOM-0018", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Infrastruktur TI & Pemulihan Bencana (DRP)", "q": "Dalam penyusunan Disaster Recovery Plan (DRP) pusat data pemerintah, parameter yang menentukan batas maksimum usia data yang boleh hilang akibat insiden bencana (diukur mundur ke belakang hingga titik pencadangan/backup terakhir) disebut...", "options": ["A. RTO (Recovery Time Objective)", "B. RPO (Recovery Point Objective)", "C. QoS (Quality of Service)", "D. MTBF (Mean Time Between Failures)", "E. SLA (Service Level Agreement)"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Jangan tertukar RPO vs RTO! RPO (Recovery Point Objective) = berapa banyak DATA masa lalu yang boleh hilang (terkait frekuensi backup). RTO (Recovery Time Objective) = berapa lama WAKTU maksimal sistem boleh mati sampai pulih kembali.", "explanation": "Pembahasan Kisi-Kisi SKB Prakom (PermenPANRB No. 32/2020 & BKN): Jangan tertukar RPO vs RTO! RPO (Recovery Point Objective) = berapa banyak DATA masa lalu yang boleh hilang (terkait frekuensi backup). RTO (Recovery Time Objective) = berapa lama WAKTU maksimal sistem boleh mati sampai pulih kembali."}, {"id": "SKB-PRAKOM-0019", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Infrastruktur TI & Penyimpanan (RAID)", "q": "Konfigurasi penyimpanan server RAID (Redundant Array of Independent Disks) yang menggabungkan teknik striping dan mirroring secara bersamaan, membutuhkan minimal 4 hard disk, serta memberikan kecepatan tinggi sekaligus toleransi kegagalan disk yang sangat baik adalah...", "options": ["A. RAID 0 (Striping murni tanpa redundansi)", "B. RAID 1 (Mirroring murni 2 disk)", "C. JBOD (Just a Bunch Of Disks)", "D. RAID 5 (Striping dengan paritas tunggal minimal 3 disk)", "E. RAID 10 (RAID 1+0)"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Hafalkan RAID: RAID 0 = Striping (cepat, 0 toleransi rusak); RAID 1 = Mirroring; RAID 5 = Striping + 1 Parity (min 3 disk); RAID 6 = 2 Parity (min 4 disk); RAID 10 = Gabungan Mirroring + Striping (min 4 disk).", "explanation": "Pembahasan Kisi-Kisi SKB Prakom (PermenPANRB No. 32/2020 & BKN): Hafalkan RAID: RAID 0 = Striping (cepat, 0 toleransi rusak); RAID 1 = Mirroring; RAID 5 = Striping + 1 Parity (min 3 disk); RAID 6 = 2 Parity (min 4 disk); RAID 10 = Gabungan Mirroring + Striping (min 4 disk)."}, {"id": "SKB-PRAKOM-0020", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Sistem Informasi Geografis (SIG) & Multimedia", "q": "Dalam Sistem Informasi Geografis (SIG / GIS), model data spasial yang merepresentasikan objek permukaan bumi menggunakan struktur titik (point), garis (line/polyline), dan luasan poligon (polygon) dengan koordinat $(X, Y)$ yang presisi disebut...", "options": ["A. Model Data Bitmap Terkompresi", "B. Model Data Tabel Relasional Non-Spasial", "C. Model Data Audio Waveform", "D. Model Data Raster (Grid Piksel)", "E. Model Data Vektor"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Dua model data spasial utama SIG: 1) Vektor = titik, garis, poligon (presisi tinggi untuk jalan, batas wilayah, lokasi gedung); 2) Raster = matriks sel/piksel (citra satelit, foto udara, DEM elevasi).", "explanation": "Pembahasan Kisi-Kisi SKB Prakom (PermenPANRB No. 32/2020 & BKN): Dua model data spasial utama SIG: 1) Vektor = titik, garis, poligon (presisi tinggi untuk jalan, batas wilayah, lokasi gedung); 2) Raster = matriks sel/piksel (citra satelit, foto udara, DEM elevasi)."}, {"id": "SKB-PRAKOM-0021", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #21:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.147.0/24`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/24` tersebut?", "options": ["A. Subnet Mask 255.255.255.0 dengan 127 usable hosts", "B. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "C. Subnet Mask 255.255.255.0 dengan 508 usable hosts", "D. Subnet Mask 255.255.255.0 dengan 254 usable hosts (terbentuk 1 subnet dari blok /24)", "E. Subnet Mask 255.255.255.0 dengan 256 usable hosts"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Untuk prefix /24: sisa bit host = 32 - 24 = 8 bit. Usable hosts = 2^8 - 2 = 254 host, dengan Subnet Mask 255.255.255.0!", "explanation": "Prefix /24 memiliki 8 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^8 = 0 (255.255.255.0), dan jumlah host valid adalah 2^8 - 2 = 254 host."}, {"id": "SKB-PRAKOM-0022", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #22), ketika terjadi kondisi di mana: 'server yang bertindak sebagai reverse proxy atau api gateway menerima respons tidak valid dari server upstream', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 502 Bad Gateway", "B. 403 Forbidden", "C. 400 Bad Request", "D. 200 OK", "E. 201 Created"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 502 Bad Gateway!", "explanation": "Kode status HTTP `502 Bad Gateway` secara spesifik merepresentasikan kondisi: Server yang bertindak sebagai reverse proxy atau API gateway menerima respons tidak valid dari server upstream."}, {"id": "SKB-PRAKOM-0023", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Multimedia & Pengolahan Citra", "q": "[Evaluasi Kompetensi Teknis Prakom #23] Format file gambar grafis berbasis vektor standar web berbasis XML yang tidak mengalami pecah (blur/pixelated) meskipun diperbesar hingga skala berapa pun adalah...", "options": ["A. SVG (Scalable Vector Graphics)", "B. PNG (Portable Network Graphics)", "C. GIF (Graphics Interchange Format)", "D. JPEG (Joint Photographic Experts Group)", "E. BMP (Bitmap Image)"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Format Vektor = SVG, EPS, AI, CDR (berbasis rumus matematis titik/kurva, tidak pecah saat di-zoom). Format Raster/Bitmap = JPEG, PNG, GIF, BMP, WEBP.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Format Vektor = SVG, EPS, AI, CDR (berbasis rumus matematis titik/kurva, tidak pecah saat di-zoom). Format Raster/Bitmap = JPEG, PNG, GIF, BMP, WEBP."}, {"id": "SKB-PRAKOM-0024", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #24:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.168.0/25`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/25` tersebut?", "options": ["A. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "B. Subnet Mask 255.255.255.128 dengan 126 usable hosts (terbentuk 2 subnet dari blok /24)", "C. Subnet Mask 255.255.255.128 dengan 128 usable hosts", "D. Subnet Mask 255.255.255.0 dengan 252 usable hosts", "E. Subnet Mask 255.255.255.128 dengan 63 usable hosts"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Untuk prefix /25: sisa bit host = 32 - 25 = 7 bit. Usable hosts = 2^7 - 2 = 126 host, dengan Subnet Mask 255.255.255.128!", "explanation": "Prefix /25 memiliki 7 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^7 = 128 (255.255.255.128), dan jumlah host valid adalah 2^7 - 2 = 126 host."}, {"id": "SKB-PRAKOM-0025", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #25), ketika terjadi kondisi di mana: 'server sedang kelebihan beban (overload) atau sedang dalam masa pemeliharaan (maintenance) sementara', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 503 Service Unavailable", "B. 403 Forbidden", "C. 201 Created", "D. 500 Internal Server Error", "E. 200 OK"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 503 Service Unavailable!", "explanation": "Kode status HTTP `503 Service Unavailable` secara spesifik merepresentasikan kondisi: Server sedang kelebihan beban (overload) atau sedang dalam masa pemeliharaan (maintenance) sementara."}, {"id": "SKB-PRAKOM-0026", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Struktur Data & Algoritma", "q": "[Evaluasi Kompetensi Teknis Prakom #26] Struktur data linier yang menerapkan prinsip LIFO (Last In, First Out) di mana elemen yang terakhir dimasukkan adalah elemen pertama yang dikeluarkan (seperti fitur Undo pada editor teks) adalah...", "options": ["A. Queue (Antrean - FIFO)", "B. Hash Table", "C. Graph Berarah", "D. Stack (Tumpukan)", "E. Binary Search Tree"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "LIFO (Last In First Out) = Stack (operasi Push & Pop). FIFO (First In First Out) = Queue (operasi Enqueue & Dequeue).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: LIFO (Last In First Out) = Stack (operasi Push & Pop). FIFO (First In First Out) = Queue (operasi Enqueue & Dequeue)."}, {"id": "SKB-PRAKOM-0027", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #27:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.189.0/26`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/26` tersebut?", "options": ["A. Subnet Mask 255.255.255.0 dengan 124 usable hosts", "B. Subnet Mask 255.255.255.192 dengan 62 usable hosts (terbentuk 4 subnet dari blok /24)", "C. Subnet Mask 255.255.255.192 dengan 31 usable hosts", "D. Subnet Mask 255.255.255.192 dengan 64 usable hosts", "E. Subnet Mask 255.255.0.0 dengan 510 usable hosts"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Untuk prefix /26: sisa bit host = 32 - 26 = 6 bit. Usable hosts = 2^6 - 2 = 62 host, dengan Subnet Mask 255.255.255.192!", "explanation": "Prefix /26 memiliki 6 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^6 = 192 (255.255.255.192), dan jumlah host valid adalah 2^6 - 2 = 62 host."}, {"id": "SKB-PRAKOM-0028", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #28), ketika terjadi kondisi di mana: 'permintaan http berhasil diproses secara normal oleh server rest api', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 503 Service Unavailable", "B. 401 Unauthorized", "C. 500 Internal Server Error", "D. 502 Bad Gateway", "E. 200 OK"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 200 OK!", "explanation": "Kode status HTTP `200 OK` secara spesifik merepresentasikan kondisi: Permintaan HTTP berhasil diproses secara normal oleh server REST API."}, {"id": "SKB-PRAKOM-0029", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Struktur Data & Algoritma", "q": "[Evaluasi Kompetensi Teknis Prakom #29] Berapakah kompleksitas waktu rata-rata (average time complexity) dari algoritma pencarian Binary Search pada sebuah array terurut berukuran $n$ elemen?", "options": ["A. O(n²)", "B. O(log n)", "C. O(n)", "D. O(2^n)", "E. O(1)"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Binary Search membagi dua ruang pencarian di setiap langkah pada data terurut, sehingga kompleksitas waktunya adalah logaritmik: O(log n).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Binary Search membagi dua ruang pencarian di setiap langkah pada data terurut, sehingga kompleksitas waktunya adalah logaritmik: O(log n)."}, {"id": "SKB-PRAKOM-0030", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #30:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.210.0/27`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/27` tersebut?", "options": ["A. Subnet Mask 255.255.255.224 dengan 15 usable hosts", "B. Subnet Mask 255.255.255.224 dengan 30 usable hosts (terbentuk 8 subnet dari blok /24)", "C. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "D. Subnet Mask 255.255.255.224 dengan 32 usable hosts", "E. Subnet Mask 255.255.255.0 dengan 60 usable hosts"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Untuk prefix /27: sisa bit host = 32 - 27 = 5 bit. Usable hosts = 2^5 - 2 = 30 host, dengan Subnet Mask 255.255.255.224!", "explanation": "Prefix /27 memiliki 5 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^5 = 224 (255.255.255.224), dan jumlah host valid adalah 2^5 - 2 = 30 host."}, {"id": "SKB-PRAKOM-0031", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #31), ketika terjadi kondisi di mana: 'permintaan http post berhasil diproses dan sumber daya (resource) baru berhasil dibuat di server', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 201 Created", "B. 200 OK", "C. 403 Forbidden", "D. 503 Service Unavailable", "E. 401 Unauthorized"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 201 Created!", "explanation": "Kode status HTTP `201 Created` secara spesifik merepresentasikan kondisi: Permintaan HTTP POST berhasil diproses dan sumber daya (resource) baru berhasil dibuat di server."}, {"id": "SKB-PRAKOM-0032", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Pemrograman Berorientasi Objek (OOP)", "q": "[Evaluasi Kompetensi Teknis Prakom #32] Prinsip dalam Object-Oriented Programming (OOP) yang membungkus atribut data dan metode di dalam satu unit kelas serta menyembunyikan detail internal menggunakan access modifier `private` disebut...", "options": ["A. Recursion (Rekursi)", "B. Inheritance (Pewarisan)", "C. Encapsulation (Enkapsulasi)", "D. Polymorphism (Polimorfisme)", "E. Abstraction Interface"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Empat pilar OOP: 1) Encapsulation (pembungkusan & penyembunyian data private), 2) Inheritance (pewarisan sifat superclass ke subclass), 3) Polymorphism (banyak bentuk method overriding/overloading), 4) Abstraction.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Empat pilar OOP: 1) Encapsulation (pembungkusan & penyembunyian data private), 2) Inheritance (pewarisan sifat superclass ke subclass), 3) Polymorphism (banyak bentuk method overriding/overloading), 4) Abstraction."}, {"id": "SKB-PRAKOM-0033", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #33:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.231.0/28`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/28` tersebut?", "options": ["A. Subnet Mask 255.255.255.240 dengan 16 usable hosts", "B. Subnet Mask 255.255.255.0 dengan 28 usable hosts", "C. Subnet Mask 255.255.255.240 dengan 14 usable hosts (terbentuk 16 subnet dari blok /24)", "D. Subnet Mask 255.255.255.240 dengan 7 usable hosts", "E. Subnet Mask 255.255.0.0 dengan 510 usable hosts"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Untuk prefix /28: sisa bit host = 32 - 28 = 4 bit. Usable hosts = 2^4 - 2 = 14 host, dengan Subnet Mask 255.255.255.240!", "explanation": "Prefix /28 memiliki 4 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^4 = 240 (255.255.255.240), dan jumlah host valid adalah 2^4 - 2 = 14 host."}, {"id": "SKB-PRAKOM-0034", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #34), ketika terjadi kondisi di mana: 'server tidak dapat memproses permintaan karena sintaks json atau parameter input dari client tidak valid', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 404 Not Found", "B. 400 Bad Request", "C. 401 Unauthorized", "D. 200 OK", "E. 403 Forbidden"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 400 Bad Request!", "explanation": "Kode status HTTP `400 Bad Request` secara spesifik merepresentasikan kondisi: Server tidak dapat memproses permintaan karena sintaks JSON atau parameter input dari client tidak valid."}, {"id": "SKB-PRAKOM-0035", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Infrastruktur Cloud Computing", "q": "[Evaluasi Kompetensi Teknis Prakom #35] Layanan komputasi awan (Cloud Computing) di mana penyedia cloud mengelola perangkat keras, jaringan, dan virtualisasi, sementara pengguna (Pranata Komputer) bertanggung jawab mengelola Sistem Operasi, Runtime, Middleware, dan Aplikasi (contoh: AWS EC2 / Google Compute Engine VM) adalah...", "options": ["A. SaaS (Software as a Service)", "B. FaaS (Function as a Service)", "C. IaaS (Infrastructure as a Service)", "D. PaaS (Platform as a Service)", "E. On-Premise Bare Metal"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Bedakan IaaS, PaaS, SaaS! IaaS = sewa VM/infrastruktur dasar (kita urus OS & aplikasi); PaaS = sewa platform siap coding (kita urus kode aplikasi & data saja); SaaS = aplikasi siap pakai (seperti Google Workspace / Microsoft 365).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Bedakan IaaS, PaaS, SaaS! IaaS = sewa VM/infrastruktur dasar (kita urus OS & aplikasi); PaaS = sewa platform siap coding (kita urus kode aplikasi & data saja); SaaS = aplikasi siap pakai (seperti Google Workspace / Microsoft 365)."}, {"id": "SKB-PRAKOM-0036", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #36:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.2.0/29`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/29` tersebut?", "options": ["A. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "B. Subnet Mask 255.255.255.248 dengan 6 usable hosts (terbentuk 32 subnet dari blok /24)", "C. Subnet Mask 255.255.255.248 dengan 3 usable hosts", "D. Subnet Mask 255.255.255.0 dengan 12 usable hosts", "E. Subnet Mask 255.255.255.248 dengan 8 usable hosts"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Untuk prefix /29: sisa bit host = 32 - 29 = 3 bit. Usable hosts = 2^3 - 2 = 6 host, dengan Subnet Mask 255.255.255.248!", "explanation": "Prefix /29 memiliki 3 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^3 = 248 (255.255.255.248), dan jumlah host valid adalah 2^3 - 2 = 6 host."}, {"id": "SKB-PRAKOM-0037", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #37), ketika terjadi kondisi di mana: 'permintaan ditolak karena client belum menyertakan token autentikasi (seperti jwt/bearer token) yang valid', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 400 Bad Request", "B. 404 Not Found", "C. 401 Unauthorized", "D. 201 Created", "E. 500 Internal Server Error"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 401 Unauthorized!", "explanation": "Kode status HTTP `401 Unauthorized` secara spesifik merepresentasikan kondisi: Permintaan ditolak karena client belum menyertakan token autentikasi (seperti JWT/Bearer Token) yang valid."}, {"id": "SKB-PRAKOM-0038", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Protokol", "q": "[Evaluasi Kompetensi Teknis Prakom #38] Protokol jaringan yang bekerja secara otomatis mendistribusikan konfigurasi alamat IP, Subnet Mask, Default Gateway, dan DNS Server kepada komputer client di dalam jaringan lokal adalah...", "options": ["A. ICMP (Internet Control Message Protocol)", "B. DNS (Domain Name System)", "C. SNMP (Simple Network Management Protocol)", "D. ARP (Address Resolution Protocol)", "E. DHCP (Dynamic Host Configuration Protocol)"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "DHCP menggunakan proses DORA (Discover, Offer, Request, Acknowledge) untuk memberikan alamat IP secara otomatis ke host client.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: DHCP menggunakan proses DORA (Discover, Offer, Request, Acknowledge) untuk memberikan alamat IP secara otomatis ke host client."}, {"id": "SKB-PRAKOM-0039", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #39:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.23.0/30`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/30` tersebut?", "options": ["A. Subnet Mask 255.255.255.252 dengan 2 usable hosts (terbentuk 64 subnet dari blok /24)", "B. Subnet Mask 255.255.255.252 dengan 4 usable hosts", "C. Subnet Mask 255.255.255.0 dengan 4 usable hosts", "D. Subnet Mask 255.255.255.252 dengan 2 usable hosts", "E. Subnet Mask 255.255.0.0 dengan 510 usable hosts"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Untuk prefix /30: sisa bit host = 32 - 30 = 2 bit. Usable hosts = 2^2 - 2 = 2 host, dengan Subnet Mask 255.255.255.252!", "explanation": "Prefix /30 memiliki 2 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^2 = 252 (255.255.255.252), dan jumlah host valid adalah 2^2 - 2 = 2 host."}, {"id": "SKB-PRAKOM-0040", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #40), ketika terjadi kondisi di mana: 'client sudah terautentikasi, namun tidak memiliki hak akses (otorisasi/role) untuk mengakses endpoint tersebut', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 403 Forbidden", "B. 400 Bad Request", "C. 200 OK", "D. 502 Bad Gateway", "E. 401 Unauthorized"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 403 Forbidden!", "explanation": "Kode status HTTP `403 Forbidden` secara spesifik merepresentasikan kondisi: Client sudah terautentikasi, namun tidak memiliki hak akses (otorisasi/role) untuk mengakses endpoint tersebut."}, {"id": "SKB-PRAKOM-0041", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Port Standar", "q": "[Evaluasi Kompetensi Teknis Prakom #41] Pasangan protokol jaringan dan nomor port TCP/UDP standar berikut ini yang BENAR dalam administrasi server Linux/Windows adalah...", "options": ["A. SMTP (Port 80), POP3 (Port 22), dan MySQL (Port 53)", "B. SSH (Port 22), HTTPS (Port 443), DNS (Port 53), dan HTTP (Port 80)", "C. Telnet (Port 443), RDP (Port 25), dan HTTPS (Port 8080)", "D. SSH (Port 80), HTTPS (Port 21), DNS (Port 443), dan FTP (Port 22)", "E. FTP (Port 53), SSH (Port 3306), dan PostgreSQL (Port 21)"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Hafalkan Port Penting SKB Prakom: FTP=20/21, SSH=22, Telnet=23, SMTP=25, DNS=53, DHCP=67/68, HTTP=80, POP3=110, IMAP=143, HTTPS=443, MySQL=3306, RDP=3389, PostgreSQL=5432.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Hafalkan Port Penting SKB Prakom: FTP=20/21, SSH=22, Telnet=23, SMTP=25, DNS=53, DHCP=67/68, HTTP=80, POP3=110, IMAP=143, HTTPS=443, MySQL=3306, RDP=3389, PostgreSQL=5432."}, {"id": "SKB-PRAKOM-0042", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #42:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.44.0/24`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/24` tersebut?", "options": ["A. Subnet Mask 255.255.255.0 dengan 508 usable hosts", "B. Subnet Mask 255.255.255.0 dengan 256 usable hosts", "C. Subnet Mask 255.255.255.0 dengan 127 usable hosts", "D. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "E. Subnet Mask 255.255.255.0 dengan 254 usable hosts (terbentuk 1 subnet dari blok /24)"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Untuk prefix /24: sisa bit host = 32 - 24 = 8 bit. Usable hosts = 2^8 - 2 = 254 host, dengan Subnet Mask 255.255.255.0!", "explanation": "Prefix /24 memiliki 8 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^8 = 0 (255.255.255.0), dan jumlah host valid adalah 2^8 - 2 = 254 host."}, {"id": "SKB-PRAKOM-0043", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #43), ketika terjadi kondisi di mana: 'endpoint url atau resource data yang diminta client tidak ditemukan di dalam server', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 403 Forbidden", "B. 200 OK", "C. 502 Bad Gateway", "D. 201 Created", "E. 404 Not Found"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 404 Not Found!", "explanation": "Kode status HTTP `404 Not Found` secara spesifik merepresentasikan kondisi: Endpoint URL atau resource data yang diminta client tidak ditemukan di dalam server."}, {"id": "SKB-PRAKOM-0044", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Audit TI & COBIT", "q": "[Evaluasi Kompetensi Teknis Prakom #44] Dalam pelaksanaan audit teknologi informasi pada instansi pemerintah, pemeriksaan terhadap pengendalian yang melekat pada aplikasi (seperti validasi input, pengendalian proses hitung, dan validasi output laporan) dikategorikan sebagai...", "options": ["A. Application Control (Pengendalian Aplikasi)", "B. Physical Security Control", "C. Environmental Control", "D. Human Resource Administrative Control", "E. IT General Control (Pengendalian Umum TI)"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Audit Sistem Informasi membagi pengendalian menjadi 2: 1) IT General Controls / ITGC (kebijakan keamanan umum, manajemen akses, backup, operasi pusat data), dan 2) Application Controls (Input Control, Processing Control, Output Control di dalam aplikasi).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Audit Sistem Informasi membagi pengendalian menjadi 2: 1) IT General Controls / ITGC (kebijakan keamanan umum, manajemen akses, backup, operasi pusat data), dan 2) Application Controls (Input Control, Processing Control, Output Control di dalam aplikasi)."}, {"id": "SKB-PRAKOM-0045", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #45:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.65.0/25`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/25` tersebut?", "options": ["A. Subnet Mask 255.255.255.0 dengan 252 usable hosts", "B. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "C. Subnet Mask 255.255.255.128 dengan 63 usable hosts", "D. Subnet Mask 255.255.255.128 dengan 126 usable hosts (terbentuk 2 subnet dari blok /24)", "E. Subnet Mask 255.255.255.128 dengan 128 usable hosts"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Untuk prefix /25: sisa bit host = 32 - 25 = 7 bit. Usable hosts = 2^7 - 2 = 126 host, dengan Subnet Mask 255.255.255.128!", "explanation": "Prefix /25 memiliki 7 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^7 = 128 (255.255.255.128), dan jumlah host valid adalah 2^7 - 2 = 126 host."}, {"id": "SKB-PRAKOM-0046", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #46), ketika terjadi kondisi di mana: 'terjadi kesalahan tak terduga pada sisi kode atau layanan backend server saat memproses permintaan', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 500 Internal Server Error", "B. 403 Forbidden", "C. 200 OK", "D. 503 Service Unavailable", "E. 201 Created"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 500 Internal Server Error!", "explanation": "Kode status HTTP `500 Internal Server Error` secara spesifik merepresentasikan kondisi: Terjadi kesalahan tak terduga pada sisi kode atau layanan backend server saat memproses permintaan."}, {"id": "SKB-PRAKOM-0047", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Multimedia & Pengolahan Citra", "q": "[Evaluasi Kompetensi Teknis Prakom #47] Format file gambar grafis berbasis vektor standar web berbasis XML yang tidak mengalami pecah (blur/pixelated) meskipun diperbesar hingga skala berapa pun adalah...", "options": ["A. GIF (Graphics Interchange Format)", "B. JPEG (Joint Photographic Experts Group)", "C. SVG (Scalable Vector Graphics)", "D. BMP (Bitmap Image)", "E. PNG (Portable Network Graphics)"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Format Vektor = SVG, EPS, AI, CDR (berbasis rumus matematis titik/kurva, tidak pecah saat di-zoom). Format Raster/Bitmap = JPEG, PNG, GIF, BMP, WEBP.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Format Vektor = SVG, EPS, AI, CDR (berbasis rumus matematis titik/kurva, tidak pecah saat di-zoom). Format Raster/Bitmap = JPEG, PNG, GIF, BMP, WEBP."}, {"id": "SKB-PRAKOM-0048", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #48:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.86.0/26`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/26` tersebut?", "options": ["A. Subnet Mask 255.255.255.0 dengan 124 usable hosts", "B. Subnet Mask 255.255.255.192 dengan 62 usable hosts (terbentuk 4 subnet dari blok /24)", "C. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "D. Subnet Mask 255.255.255.192 dengan 31 usable hosts", "E. Subnet Mask 255.255.255.192 dengan 64 usable hosts"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Untuk prefix /26: sisa bit host = 32 - 26 = 6 bit. Usable hosts = 2^6 - 2 = 62 host, dengan Subnet Mask 255.255.255.192!", "explanation": "Prefix /26 memiliki 6 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^6 = 192 (255.255.255.192), dan jumlah host valid adalah 2^6 - 2 = 62 host."}, {"id": "SKB-PRAKOM-0049", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #49), ketika terjadi kondisi di mana: 'server yang bertindak sebagai reverse proxy atau api gateway menerima respons tidak valid dari server upstream', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 200 OK", "B. 403 Forbidden", "C. 400 Bad Request", "D. 401 Unauthorized", "E. 502 Bad Gateway"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 502 Bad Gateway!", "explanation": "Kode status HTTP `502 Bad Gateway` secara spesifik merepresentasikan kondisi: Server yang bertindak sebagai reverse proxy atau API gateway menerima respons tidak valid dari server upstream."}, {"id": "SKB-PRAKOM-0050", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Struktur Data & Algoritma", "q": "[Evaluasi Kompetensi Teknis Prakom #50] Struktur data linier yang menerapkan prinsip LIFO (Last In, First Out) di mana elemen yang terakhir dimasukkan adalah elemen pertama yang dikeluarkan (seperti fitur Undo pada editor teks) adalah...", "options": ["A. Graph Berarah", "B. Binary Search Tree", "C. Hash Table", "D. Queue (Antrean - FIFO)", "E. Stack (Tumpukan)"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "LIFO (Last In First Out) = Stack (operasi Push & Pop). FIFO (First In First Out) = Queue (operasi Enqueue & Dequeue).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: LIFO (Last In First Out) = Stack (operasi Push & Pop). FIFO (First In First Out) = Queue (operasi Enqueue & Dequeue)."}, {"id": "SKB-PRAKOM-0051", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #51:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.107.0/27`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/27` tersebut?", "options": ["A. Subnet Mask 255.255.255.224 dengan 30 usable hosts (terbentuk 8 subnet dari blok /24)", "B. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "C. Subnet Mask 255.255.255.0 dengan 60 usable hosts", "D. Subnet Mask 255.255.255.224 dengan 32 usable hosts", "E. Subnet Mask 255.255.255.224 dengan 15 usable hosts"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Untuk prefix /27: sisa bit host = 32 - 27 = 5 bit. Usable hosts = 2^5 - 2 = 30 host, dengan Subnet Mask 255.255.255.224!", "explanation": "Prefix /27 memiliki 5 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^5 = 224 (255.255.255.224), dan jumlah host valid adalah 2^5 - 2 = 30 host."}, {"id": "SKB-PRAKOM-0052", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #52), ketika terjadi kondisi di mana: 'server sedang kelebihan beban (overload) atau sedang dalam masa pemeliharaan (maintenance) sementara', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 400 Bad Request", "B. 403 Forbidden", "C. 502 Bad Gateway", "D. 503 Service Unavailable", "E. 404 Not Found"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 503 Service Unavailable!", "explanation": "Kode status HTTP `503 Service Unavailable` secara spesifik merepresentasikan kondisi: Server sedang kelebihan beban (overload) atau sedang dalam masa pemeliharaan (maintenance) sementara."}, {"id": "SKB-PRAKOM-0053", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Struktur Data & Algoritma", "q": "[Evaluasi Kompetensi Teknis Prakom #53] Berapakah kompleksitas waktu rata-rata (average time complexity) dari algoritma pencarian Binary Search pada sebuah array terurut berukuran $n$ elemen?", "options": ["A. O(n²)", "B. O(log n)", "C. O(2^n)", "D. O(1)", "E. O(n)"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Binary Search membagi dua ruang pencarian di setiap langkah pada data terurut, sehingga kompleksitas waktunya adalah logaritmik: O(log n).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Binary Search membagi dua ruang pencarian di setiap langkah pada data terurut, sehingga kompleksitas waktunya adalah logaritmik: O(log n)."}, {"id": "SKB-PRAKOM-0054", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #54:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.128.0/28`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/28` tersebut?", "options": ["A. Subnet Mask 255.255.255.0 dengan 28 usable hosts", "B. Subnet Mask 255.255.255.240 dengan 16 usable hosts", "C. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "D. Subnet Mask 255.255.255.240 dengan 14 usable hosts (terbentuk 16 subnet dari blok /24)", "E. Subnet Mask 255.255.255.240 dengan 7 usable hosts"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Untuk prefix /28: sisa bit host = 32 - 28 = 4 bit. Usable hosts = 2^4 - 2 = 14 host, dengan Subnet Mask 255.255.255.240!", "explanation": "Prefix /28 memiliki 4 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^4 = 240 (255.255.255.240), dan jumlah host valid adalah 2^4 - 2 = 14 host."}, {"id": "SKB-PRAKOM-0055", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #55), ketika terjadi kondisi di mana: 'permintaan http berhasil diproses secara normal oleh server rest api', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 400 Bad Request", "B. 404 Not Found", "C. 200 OK", "D. 401 Unauthorized", "E. 503 Service Unavailable"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 200 OK!", "explanation": "Kode status HTTP `200 OK` secara spesifik merepresentasikan kondisi: Permintaan HTTP berhasil diproses secara normal oleh server REST API."}, {"id": "SKB-PRAKOM-0056", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Pemrograman Berorientasi Objek (OOP)", "q": "[Evaluasi Kompetensi Teknis Prakom #56] Prinsip dalam Object-Oriented Programming (OOP) yang membungkus atribut data dan metode di dalam satu unit kelas serta menyembunyikan detail internal menggunakan access modifier `private` disebut...", "options": ["A. Recursion (Rekursi)", "B. Inheritance (Pewarisan)", "C. Encapsulation (Enkapsulasi)", "D. Abstraction Interface", "E. Polymorphism (Polimorfisme)"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Empat pilar OOP: 1) Encapsulation (pembungkusan & penyembunyian data private), 2) Inheritance (pewarisan sifat superclass ke subclass), 3) Polymorphism (banyak bentuk method overriding/overloading), 4) Abstraction.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Empat pilar OOP: 1) Encapsulation (pembungkusan & penyembunyian data private), 2) Inheritance (pewarisan sifat superclass ke subclass), 3) Polymorphism (banyak bentuk method overriding/overloading), 4) Abstraction."}, {"id": "SKB-PRAKOM-0057", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #57:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.149.0/29`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/29` tersebut?", "options": ["A. Subnet Mask 255.255.255.248 dengan 6 usable hosts (terbentuk 32 subnet dari blok /24)", "B. Subnet Mask 255.255.255.248 dengan 8 usable hosts", "C. Subnet Mask 255.255.255.248 dengan 3 usable hosts", "D. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "E. Subnet Mask 255.255.255.0 dengan 12 usable hosts"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Untuk prefix /29: sisa bit host = 32 - 29 = 3 bit. Usable hosts = 2^3 - 2 = 6 host, dengan Subnet Mask 255.255.255.248!", "explanation": "Prefix /29 memiliki 3 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^3 = 248 (255.255.255.248), dan jumlah host valid adalah 2^3 - 2 = 6 host."}, {"id": "SKB-PRAKOM-0058", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #58), ketika terjadi kondisi di mana: 'permintaan http post berhasil diproses dan sumber daya (resource) baru berhasil dibuat di server', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 401 Unauthorized", "B. 400 Bad Request", "C. 201 Created", "D. 200 OK", "E. 403 Forbidden"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 201 Created!", "explanation": "Kode status HTTP `201 Created` secara spesifik merepresentasikan kondisi: Permintaan HTTP POST berhasil diproses dan sumber daya (resource) baru berhasil dibuat di server."}, {"id": "SKB-PRAKOM-0059", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Infrastruktur Cloud Computing", "q": "[Evaluasi Kompetensi Teknis Prakom #59] Layanan komputasi awan (Cloud Computing) di mana penyedia cloud mengelola perangkat keras, jaringan, dan virtualisasi, sementara pengguna (Pranata Komputer) bertanggung jawab mengelola Sistem Operasi, Runtime, Middleware, dan Aplikasi (contoh: AWS EC2 / Google Compute Engine VM) adalah...", "options": ["A. FaaS (Function as a Service)", "B. IaaS (Infrastructure as a Service)", "C. On-Premise Bare Metal", "D. SaaS (Software as a Service)", "E. PaaS (Platform as a Service)"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Bedakan IaaS, PaaS, SaaS! IaaS = sewa VM/infrastruktur dasar (kita urus OS & aplikasi); PaaS = sewa platform siap coding (kita urus kode aplikasi & data saja); SaaS = aplikasi siap pakai (seperti Google Workspace / Microsoft 365).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Bedakan IaaS, PaaS, SaaS! IaaS = sewa VM/infrastruktur dasar (kita urus OS & aplikasi); PaaS = sewa platform siap coding (kita urus kode aplikasi & data saja); SaaS = aplikasi siap pakai (seperti Google Workspace / Microsoft 365)."}, {"id": "SKB-PRAKOM-0060", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #60:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.170.0/30`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/30` tersebut?", "options": ["A. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "B. Subnet Mask 255.255.255.252 dengan 2 usable hosts", "C. Subnet Mask 255.255.255.252 dengan 4 usable hosts", "D. Subnet Mask 255.255.255.252 dengan 2 usable hosts (terbentuk 64 subnet dari blok /24)", "E. Subnet Mask 255.255.255.0 dengan 4 usable hosts"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Untuk prefix /30: sisa bit host = 32 - 30 = 2 bit. Usable hosts = 2^2 - 2 = 2 host, dengan Subnet Mask 255.255.255.252!", "explanation": "Prefix /30 memiliki 2 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^2 = 252 (255.255.255.252), dan jumlah host valid adalah 2^2 - 2 = 2 host."}, {"id": "SKB-PRAKOM-0061", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #61), ketika terjadi kondisi di mana: 'server tidak dapat memproses permintaan karena sintaks json atau parameter input dari client tidak valid', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 502 Bad Gateway", "B. 401 Unauthorized", "C. 500 Internal Server Error", "D. 404 Not Found", "E. 400 Bad Request"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 400 Bad Request!", "explanation": "Kode status HTTP `400 Bad Request` secara spesifik merepresentasikan kondisi: Server tidak dapat memproses permintaan karena sintaks JSON atau parameter input dari client tidak valid."}, {"id": "SKB-PRAKOM-0062", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Protokol", "q": "[Evaluasi Kompetensi Teknis Prakom #62] Protokol jaringan yang bekerja secara otomatis mendistribusikan konfigurasi alamat IP, Subnet Mask, Default Gateway, dan DNS Server kepada komputer client di dalam jaringan lokal adalah...", "options": ["A. SNMP (Simple Network Management Protocol)", "B. DNS (Domain Name System)", "C. ICMP (Internet Control Message Protocol)", "D. DHCP (Dynamic Host Configuration Protocol)", "E. ARP (Address Resolution Protocol)"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "DHCP menggunakan proses DORA (Discover, Offer, Request, Acknowledge) untuk memberikan alamat IP secara otomatis ke host client.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: DHCP menggunakan proses DORA (Discover, Offer, Request, Acknowledge) untuk memberikan alamat IP secara otomatis ke host client."}, {"id": "SKB-PRAKOM-0063", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #63:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.191.0/24`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/24` tersebut?", "options": ["A. Subnet Mask 255.255.255.0 dengan 508 usable hosts", "B. Subnet Mask 255.255.255.0 dengan 127 usable hosts", "C. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "D. Subnet Mask 255.255.255.0 dengan 254 usable hosts (terbentuk 1 subnet dari blok /24)", "E. Subnet Mask 255.255.255.0 dengan 256 usable hosts"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Untuk prefix /24: sisa bit host = 32 - 24 = 8 bit. Usable hosts = 2^8 - 2 = 254 host, dengan Subnet Mask 255.255.255.0!", "explanation": "Prefix /24 memiliki 8 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^8 = 0 (255.255.255.0), dan jumlah host valid adalah 2^8 - 2 = 254 host."}, {"id": "SKB-PRAKOM-0064", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #64), ketika terjadi kondisi di mana: 'permintaan ditolak karena client belum menyertakan token autentikasi (seperti jwt/bearer token) yang valid', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 500 Internal Server Error", "B. 503 Service Unavailable", "C. 401 Unauthorized", "D. 200 OK", "E. 400 Bad Request"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 401 Unauthorized!", "explanation": "Kode status HTTP `401 Unauthorized` secara spesifik merepresentasikan kondisi: Permintaan ditolak karena client belum menyertakan token autentikasi (seperti JWT/Bearer Token) yang valid."}, {"id": "SKB-PRAKOM-0065", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Port Standar", "q": "[Evaluasi Kompetensi Teknis Prakom #65] Pasangan protokol jaringan dan nomor port TCP/UDP standar berikut ini yang BENAR dalam administrasi server Linux/Windows adalah...", "options": ["A. SSH (Port 22), HTTPS (Port 443), DNS (Port 53), dan HTTP (Port 80)", "B. FTP (Port 53), SSH (Port 3306), dan PostgreSQL (Port 21)", "C. Telnet (Port 443), RDP (Port 25), dan HTTPS (Port 8080)", "D. SSH (Port 80), HTTPS (Port 21), DNS (Port 443), dan FTP (Port 22)", "E. SMTP (Port 80), POP3 (Port 22), dan MySQL (Port 53)"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Hafalkan Port Penting SKB Prakom: FTP=20/21, SSH=22, Telnet=23, SMTP=25, DNS=53, DHCP=67/68, HTTP=80, POP3=110, IMAP=143, HTTPS=443, MySQL=3306, RDP=3389, PostgreSQL=5432.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Hafalkan Port Penting SKB Prakom: FTP=20/21, SSH=22, Telnet=23, SMTP=25, DNS=53, DHCP=67/68, HTTP=80, POP3=110, IMAP=143, HTTPS=443, MySQL=3306, RDP=3389, PostgreSQL=5432."}, {"id": "SKB-PRAKOM-0066", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #66:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.212.0/25`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/25` tersebut?", "options": ["A. Subnet Mask 255.255.255.128 dengan 128 usable hosts", "B. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "C. Subnet Mask 255.255.255.0 dengan 252 usable hosts", "D. Subnet Mask 255.255.255.128 dengan 63 usable hosts", "E. Subnet Mask 255.255.255.128 dengan 126 usable hosts (terbentuk 2 subnet dari blok /24)"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Untuk prefix /25: sisa bit host = 32 - 25 = 7 bit. Usable hosts = 2^7 - 2 = 126 host, dengan Subnet Mask 255.255.255.128!", "explanation": "Prefix /25 memiliki 7 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^7 = 128 (255.255.255.128), dan jumlah host valid adalah 2^7 - 2 = 126 host."}, {"id": "SKB-PRAKOM-0067", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #67), ketika terjadi kondisi di mana: 'client sudah terautentikasi, namun tidak memiliki hak akses (otorisasi/role) untuk mengakses endpoint tersebut', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 404 Not Found", "B. 403 Forbidden", "C. 401 Unauthorized", "D. 502 Bad Gateway", "E. 201 Created"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 403 Forbidden!", "explanation": "Kode status HTTP `403 Forbidden` secara spesifik merepresentasikan kondisi: Client sudah terautentikasi, namun tidak memiliki hak akses (otorisasi/role) untuk mengakses endpoint tersebut."}, {"id": "SKB-PRAKOM-0068", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Audit TI & COBIT", "q": "[Evaluasi Kompetensi Teknis Prakom #68] Dalam pelaksanaan audit teknologi informasi pada instansi pemerintah, pemeriksaan terhadap pengendalian yang melekat pada aplikasi (seperti validasi input, pengendalian proses hitung, dan validasi output laporan) dikategorikan sebagai...", "options": ["A. Human Resource Administrative Control", "B. Application Control (Pengendalian Aplikasi)", "C. Environmental Control", "D. Physical Security Control", "E. IT General Control (Pengendalian Umum TI)"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Audit Sistem Informasi membagi pengendalian menjadi 2: 1) IT General Controls / ITGC (kebijakan keamanan umum, manajemen akses, backup, operasi pusat data), dan 2) Application Controls (Input Control, Processing Control, Output Control di dalam aplikasi).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Audit Sistem Informasi membagi pengendalian menjadi 2: 1) IT General Controls / ITGC (kebijakan keamanan umum, manajemen akses, backup, operasi pusat data), dan 2) Application Controls (Input Control, Processing Control, Output Control di dalam aplikasi)."}, {"id": "SKB-PRAKOM-0069", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #69:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.233.0/26`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/26` tersebut?", "options": ["A. Subnet Mask 255.255.255.192 dengan 64 usable hosts", "B. Subnet Mask 255.255.255.192 dengan 62 usable hosts (terbentuk 4 subnet dari blok /24)", "C. Subnet Mask 255.255.255.192 dengan 31 usable hosts", "D. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "E. Subnet Mask 255.255.255.0 dengan 124 usable hosts"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Untuk prefix /26: sisa bit host = 32 - 26 = 6 bit. Usable hosts = 2^6 - 2 = 62 host, dengan Subnet Mask 255.255.255.192!", "explanation": "Prefix /26 memiliki 6 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^6 = 192 (255.255.255.192), dan jumlah host valid adalah 2^6 - 2 = 62 host."}, {"id": "SKB-PRAKOM-0070", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #70), ketika terjadi kondisi di mana: 'endpoint url atau resource data yang diminta client tidak ditemukan di dalam server', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 502 Bad Gateway", "B. 403 Forbidden", "C. 200 OK", "D. 500 Internal Server Error", "E. 404 Not Found"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 404 Not Found!", "explanation": "Kode status HTTP `404 Not Found` secara spesifik merepresentasikan kondisi: Endpoint URL atau resource data yang diminta client tidak ditemukan di dalam server."}, {"id": "SKB-PRAKOM-0071", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Multimedia & Pengolahan Citra", "q": "[Evaluasi Kompetensi Teknis Prakom #71] Format file gambar grafis berbasis vektor standar web berbasis XML yang tidak mengalami pecah (blur/pixelated) meskipun diperbesar hingga skala berapa pun adalah...", "options": ["A. JPEG (Joint Photographic Experts Group)", "B. SVG (Scalable Vector Graphics)", "C. BMP (Bitmap Image)", "D. PNG (Portable Network Graphics)", "E. GIF (Graphics Interchange Format)"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Format Vektor = SVG, EPS, AI, CDR (berbasis rumus matematis titik/kurva, tidak pecah saat di-zoom). Format Raster/Bitmap = JPEG, PNG, GIF, BMP, WEBP.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Format Vektor = SVG, EPS, AI, CDR (berbasis rumus matematis titik/kurva, tidak pecah saat di-zoom). Format Raster/Bitmap = JPEG, PNG, GIF, BMP, WEBP."}, {"id": "SKB-PRAKOM-0072", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #72:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.4.0/27`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/27` tersebut?", "options": ["A. Subnet Mask 255.255.255.224 dengan 30 usable hosts (terbentuk 8 subnet dari blok /24)", "B. Subnet Mask 255.255.255.224 dengan 15 usable hosts", "C. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "D. Subnet Mask 255.255.255.224 dengan 32 usable hosts", "E. Subnet Mask 255.255.255.0 dengan 60 usable hosts"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Untuk prefix /27: sisa bit host = 32 - 27 = 5 bit. Usable hosts = 2^5 - 2 = 30 host, dengan Subnet Mask 255.255.255.224!", "explanation": "Prefix /27 memiliki 5 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^5 = 224 (255.255.255.224), dan jumlah host valid adalah 2^5 - 2 = 30 host."}, {"id": "SKB-PRAKOM-0073", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #73), ketika terjadi kondisi di mana: 'terjadi kesalahan tak terduga pada sisi kode atau layanan backend server saat memproses permintaan', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 200 OK", "B. 500 Internal Server Error", "C. 503 Service Unavailable", "D. 404 Not Found", "E. 400 Bad Request"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 500 Internal Server Error!", "explanation": "Kode status HTTP `500 Internal Server Error` secara spesifik merepresentasikan kondisi: Terjadi kesalahan tak terduga pada sisi kode atau layanan backend server saat memproses permintaan."}, {"id": "SKB-PRAKOM-0074", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Struktur Data & Algoritma", "q": "[Evaluasi Kompetensi Teknis Prakom #74] Struktur data linier yang menerapkan prinsip LIFO (Last In, First Out) di mana elemen yang terakhir dimasukkan adalah elemen pertama yang dikeluarkan (seperti fitur Undo pada editor teks) adalah...", "options": ["A. Stack (Tumpukan)", "B. Hash Table", "C. Binary Search Tree", "D. Queue (Antrean - FIFO)", "E. Graph Berarah"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "LIFO (Last In First Out) = Stack (operasi Push & Pop). FIFO (First In First Out) = Queue (operasi Enqueue & Dequeue).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: LIFO (Last In First Out) = Stack (operasi Push & Pop). FIFO (First In First Out) = Queue (operasi Enqueue & Dequeue)."}, {"id": "SKB-PRAKOM-0075", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #75:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.25.0/28`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/28` tersebut?", "options": ["A. Subnet Mask 255.255.255.240 dengan 7 usable hosts", "B. Subnet Mask 255.255.255.240 dengan 14 usable hosts (terbentuk 16 subnet dari blok /24)", "C. Subnet Mask 255.255.255.240 dengan 16 usable hosts", "D. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "E. Subnet Mask 255.255.255.0 dengan 28 usable hosts"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Untuk prefix /28: sisa bit host = 32 - 28 = 4 bit. Usable hosts = 2^4 - 2 = 14 host, dengan Subnet Mask 255.255.255.240!", "explanation": "Prefix /28 memiliki 4 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^4 = 240 (255.255.255.240), dan jumlah host valid adalah 2^4 - 2 = 14 host."}, {"id": "SKB-PRAKOM-0076", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #76), ketika terjadi kondisi di mana: 'server yang bertindak sebagai reverse proxy atau api gateway menerima respons tidak valid dari server upstream', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 502 Bad Gateway", "B. 503 Service Unavailable", "C. 400 Bad Request", "D. 201 Created", "E. 200 OK"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 502 Bad Gateway!", "explanation": "Kode status HTTP `502 Bad Gateway` secara spesifik merepresentasikan kondisi: Server yang bertindak sebagai reverse proxy atau API gateway menerima respons tidak valid dari server upstream."}, {"id": "SKB-PRAKOM-0077", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Struktur Data & Algoritma", "q": "[Evaluasi Kompetensi Teknis Prakom #77] Berapakah kompleksitas waktu rata-rata (average time complexity) dari algoritma pencarian Binary Search pada sebuah array terurut berukuran $n$ elemen?", "options": ["A. O(2^n)", "B. O(log n)", "C. O(1)", "D. O(n)", "E. O(n²)"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Binary Search membagi dua ruang pencarian di setiap langkah pada data terurut, sehingga kompleksitas waktunya adalah logaritmik: O(log n).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Binary Search membagi dua ruang pencarian di setiap langkah pada data terurut, sehingga kompleksitas waktunya adalah logaritmik: O(log n)."}, {"id": "SKB-PRAKOM-0078", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #78:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.46.0/29`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/29` tersebut?", "options": ["A. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "B. Subnet Mask 255.255.255.248 dengan 3 usable hosts", "C. Subnet Mask 255.255.255.0 dengan 12 usable hosts", "D. Subnet Mask 255.255.255.248 dengan 6 usable hosts (terbentuk 32 subnet dari blok /24)", "E. Subnet Mask 255.255.255.248 dengan 8 usable hosts"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Untuk prefix /29: sisa bit host = 32 - 29 = 3 bit. Usable hosts = 2^3 - 2 = 6 host, dengan Subnet Mask 255.255.255.248!", "explanation": "Prefix /29 memiliki 3 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^3 = 248 (255.255.255.248), dan jumlah host valid adalah 2^3 - 2 = 6 host."}, {"id": "SKB-PRAKOM-0079", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #79), ketika terjadi kondisi di mana: 'server sedang kelebihan beban (overload) atau sedang dalam masa pemeliharaan (maintenance) sementara', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 200 OK", "B. 503 Service Unavailable", "C. 502 Bad Gateway", "D. 500 Internal Server Error", "E. 403 Forbidden"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 503 Service Unavailable!", "explanation": "Kode status HTTP `503 Service Unavailable` secara spesifik merepresentasikan kondisi: Server sedang kelebihan beban (overload) atau sedang dalam masa pemeliharaan (maintenance) sementara."}, {"id": "SKB-PRAKOM-0080", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Pemrograman Berorientasi Objek (OOP)", "q": "[Evaluasi Kompetensi Teknis Prakom #80] Prinsip dalam Object-Oriented Programming (OOP) yang membungkus atribut data dan metode di dalam satu unit kelas serta menyembunyikan detail internal menggunakan access modifier `private` disebut...", "options": ["A. Recursion (Rekursi)", "B. Inheritance (Pewarisan)", "C. Encapsulation (Enkapsulasi)", "D. Abstraction Interface", "E. Polymorphism (Polimorfisme)"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Empat pilar OOP: 1) Encapsulation (pembungkusan & penyembunyian data private), 2) Inheritance (pewarisan sifat superclass ke subclass), 3) Polymorphism (banyak bentuk method overriding/overloading), 4) Abstraction.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Empat pilar OOP: 1) Encapsulation (pembungkusan & penyembunyian data private), 2) Inheritance (pewarisan sifat superclass ke subclass), 3) Polymorphism (banyak bentuk method overriding/overloading), 4) Abstraction."}, {"id": "SKB-PRAKOM-0081", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #81:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.67.0/30`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/30` tersebut?", "options": ["A. Subnet Mask 255.255.255.252 dengan 2 usable hosts (terbentuk 64 subnet dari blok /24)", "B. Subnet Mask 255.255.255.252 dengan 2 usable hosts", "C. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "D. Subnet Mask 255.255.255.0 dengan 4 usable hosts", "E. Subnet Mask 255.255.255.252 dengan 4 usable hosts"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Untuk prefix /30: sisa bit host = 32 - 30 = 2 bit. Usable hosts = 2^2 - 2 = 2 host, dengan Subnet Mask 255.255.255.252!", "explanation": "Prefix /30 memiliki 2 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^2 = 252 (255.255.255.252), dan jumlah host valid adalah 2^2 - 2 = 2 host."}, {"id": "SKB-PRAKOM-0082", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #82), ketika terjadi kondisi di mana: 'permintaan http berhasil diproses secara normal oleh server rest api', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 200 OK", "B. 503 Service Unavailable", "C. 201 Created", "D. 400 Bad Request", "E. 403 Forbidden"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 200 OK!", "explanation": "Kode status HTTP `200 OK` secara spesifik merepresentasikan kondisi: Permintaan HTTP berhasil diproses secara normal oleh server REST API."}, {"id": "SKB-PRAKOM-0083", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Infrastruktur Cloud Computing", "q": "[Evaluasi Kompetensi Teknis Prakom #83] Layanan komputasi awan (Cloud Computing) di mana penyedia cloud mengelola perangkat keras, jaringan, dan virtualisasi, sementara pengguna (Pranata Komputer) bertanggung jawab mengelola Sistem Operasi, Runtime, Middleware, dan Aplikasi (contoh: AWS EC2 / Google Compute Engine VM) adalah...", "options": ["A. PaaS (Platform as a Service)", "B. IaaS (Infrastructure as a Service)", "C. On-Premise Bare Metal", "D. FaaS (Function as a Service)", "E. SaaS (Software as a Service)"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Bedakan IaaS, PaaS, SaaS! IaaS = sewa VM/infrastruktur dasar (kita urus OS & aplikasi); PaaS = sewa platform siap coding (kita urus kode aplikasi & data saja); SaaS = aplikasi siap pakai (seperti Google Workspace / Microsoft 365).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Bedakan IaaS, PaaS, SaaS! IaaS = sewa VM/infrastruktur dasar (kita urus OS & aplikasi); PaaS = sewa platform siap coding (kita urus kode aplikasi & data saja); SaaS = aplikasi siap pakai (seperti Google Workspace / Microsoft 365)."}, {"id": "SKB-PRAKOM-0084", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #84:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.88.0/24`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/24` tersebut?", "options": ["A. Subnet Mask 255.255.255.0 dengan 254 usable hosts (terbentuk 1 subnet dari blok /24)", "B. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "C. Subnet Mask 255.255.255.0 dengan 127 usable hosts", "D. Subnet Mask 255.255.255.0 dengan 508 usable hosts", "E. Subnet Mask 255.255.255.0 dengan 256 usable hosts"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Untuk prefix /24: sisa bit host = 32 - 24 = 8 bit. Usable hosts = 2^8 - 2 = 254 host, dengan Subnet Mask 255.255.255.0!", "explanation": "Prefix /24 memiliki 8 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^8 = 0 (255.255.255.0), dan jumlah host valid adalah 2^8 - 2 = 254 host."}, {"id": "SKB-PRAKOM-0085", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #85), ketika terjadi kondisi di mana: 'permintaan http post berhasil diproses dan sumber daya (resource) baru berhasil dibuat di server', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 500 Internal Server Error", "B. 502 Bad Gateway", "C. 404 Not Found", "D. 201 Created", "E. 400 Bad Request"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 201 Created!", "explanation": "Kode status HTTP `201 Created` secara spesifik merepresentasikan kondisi: Permintaan HTTP POST berhasil diproses dan sumber daya (resource) baru berhasil dibuat di server."}, {"id": "SKB-PRAKOM-0086", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Protokol", "q": "[Evaluasi Kompetensi Teknis Prakom #86] Protokol jaringan yang bekerja secara otomatis mendistribusikan konfigurasi alamat IP, Subnet Mask, Default Gateway, dan DNS Server kepada komputer client di dalam jaringan lokal adalah...", "options": ["A. SNMP (Simple Network Management Protocol)", "B. DNS (Domain Name System)", "C. ARP (Address Resolution Protocol)", "D. ICMP (Internet Control Message Protocol)", "E. DHCP (Dynamic Host Configuration Protocol)"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "DHCP menggunakan proses DORA (Discover, Offer, Request, Acknowledge) untuk memberikan alamat IP secara otomatis ke host client.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: DHCP menggunakan proses DORA (Discover, Offer, Request, Acknowledge) untuk memberikan alamat IP secara otomatis ke host client."}, {"id": "SKB-PRAKOM-0087", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #87:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.109.0/25`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/25` tersebut?", "options": ["A. Subnet Mask 255.255.255.0 dengan 252 usable hosts", "B. Subnet Mask 255.255.255.128 dengan 63 usable hosts", "C. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "D. Subnet Mask 255.255.255.128 dengan 126 usable hosts (terbentuk 2 subnet dari blok /24)", "E. Subnet Mask 255.255.255.128 dengan 128 usable hosts"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Untuk prefix /25: sisa bit host = 32 - 25 = 7 bit. Usable hosts = 2^7 - 2 = 126 host, dengan Subnet Mask 255.255.255.128!", "explanation": "Prefix /25 memiliki 7 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^7 = 128 (255.255.255.128), dan jumlah host valid adalah 2^7 - 2 = 126 host."}, {"id": "SKB-PRAKOM-0088", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #88), ketika terjadi kondisi di mana: 'server tidak dapat memproses permintaan karena sintaks json atau parameter input dari client tidak valid', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 400 Bad Request", "B. 403 Forbidden", "C. 401 Unauthorized", "D. 502 Bad Gateway", "E. 500 Internal Server Error"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 400 Bad Request!", "explanation": "Kode status HTTP `400 Bad Request` secara spesifik merepresentasikan kondisi: Server tidak dapat memproses permintaan karena sintaks JSON atau parameter input dari client tidak valid."}, {"id": "SKB-PRAKOM-0089", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Port Standar", "q": "[Evaluasi Kompetensi Teknis Prakom #89] Pasangan protokol jaringan dan nomor port TCP/UDP standar berikut ini yang BENAR dalam administrasi server Linux/Windows adalah...", "options": ["A. SSH (Port 80), HTTPS (Port 21), DNS (Port 443), dan FTP (Port 22)", "B. FTP (Port 53), SSH (Port 3306), dan PostgreSQL (Port 21)", "C. Telnet (Port 443), RDP (Port 25), dan HTTPS (Port 8080)", "D. SSH (Port 22), HTTPS (Port 443), DNS (Port 53), dan HTTP (Port 80)", "E. SMTP (Port 80), POP3 (Port 22), dan MySQL (Port 53)"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Hafalkan Port Penting SKB Prakom: FTP=20/21, SSH=22, Telnet=23, SMTP=25, DNS=53, DHCP=67/68, HTTP=80, POP3=110, IMAP=143, HTTPS=443, MySQL=3306, RDP=3389, PostgreSQL=5432.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Hafalkan Port Penting SKB Prakom: FTP=20/21, SSH=22, Telnet=23, SMTP=25, DNS=53, DHCP=67/68, HTTP=80, POP3=110, IMAP=143, HTTPS=443, MySQL=3306, RDP=3389, PostgreSQL=5432."}, {"id": "SKB-PRAKOM-0090", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #90:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.130.0/26`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/26` tersebut?", "options": ["A. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "B. Subnet Mask 255.255.255.192 dengan 62 usable hosts (terbentuk 4 subnet dari blok /24)", "C. Subnet Mask 255.255.255.192 dengan 64 usable hosts", "D. Subnet Mask 255.255.255.0 dengan 124 usable hosts", "E. Subnet Mask 255.255.255.192 dengan 31 usable hosts"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Untuk prefix /26: sisa bit host = 32 - 26 = 6 bit. Usable hosts = 2^6 - 2 = 62 host, dengan Subnet Mask 255.255.255.192!", "explanation": "Prefix /26 memiliki 6 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^6 = 192 (255.255.255.192), dan jumlah host valid adalah 2^6 - 2 = 62 host."}, {"id": "SKB-PRAKOM-0091", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #91), ketika terjadi kondisi di mana: 'permintaan ditolak karena client belum menyertakan token autentikasi (seperti jwt/bearer token) yang valid', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 200 OK", "B. 500 Internal Server Error", "C. 503 Service Unavailable", "D. 201 Created", "E. 401 Unauthorized"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 401 Unauthorized!", "explanation": "Kode status HTTP `401 Unauthorized` secara spesifik merepresentasikan kondisi: Permintaan ditolak karena client belum menyertakan token autentikasi (seperti JWT/Bearer Token) yang valid."}, {"id": "SKB-PRAKOM-0092", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Audit TI & COBIT", "q": "[Evaluasi Kompetensi Teknis Prakom #92] Dalam pelaksanaan audit teknologi informasi pada instansi pemerintah, pemeriksaan terhadap pengendalian yang melekat pada aplikasi (seperti validasi input, pengendalian proses hitung, dan validasi output laporan) dikategorikan sebagai...", "options": ["A. IT General Control (Pengendalian Umum TI)", "B. Physical Security Control", "C. Application Control (Pengendalian Aplikasi)", "D. Environmental Control", "E. Human Resource Administrative Control"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Audit Sistem Informasi membagi pengendalian menjadi 2: 1) IT General Controls / ITGC (kebijakan keamanan umum, manajemen akses, backup, operasi pusat data), dan 2) Application Controls (Input Control, Processing Control, Output Control di dalam aplikasi).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Audit Sistem Informasi membagi pengendalian menjadi 2: 1) IT General Controls / ITGC (kebijakan keamanan umum, manajemen akses, backup, operasi pusat data), dan 2) Application Controls (Input Control, Processing Control, Output Control di dalam aplikasi)."}, {"id": "SKB-PRAKOM-0093", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #93:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.151.0/27`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/27` tersebut?", "options": ["A. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "B. Subnet Mask 255.255.255.224 dengan 30 usable hosts (terbentuk 8 subnet dari blok /24)", "C. Subnet Mask 255.255.255.224 dengan 32 usable hosts", "D. Subnet Mask 255.255.255.224 dengan 15 usable hosts", "E. Subnet Mask 255.255.255.0 dengan 60 usable hosts"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Untuk prefix /27: sisa bit host = 32 - 27 = 5 bit. Usable hosts = 2^5 - 2 = 30 host, dengan Subnet Mask 255.255.255.224!", "explanation": "Prefix /27 memiliki 5 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^5 = 224 (255.255.255.224), dan jumlah host valid adalah 2^5 - 2 = 30 host."}, {"id": "SKB-PRAKOM-0094", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #94), ketika terjadi kondisi di mana: 'client sudah terautentikasi, namun tidak memiliki hak akses (otorisasi/role) untuk mengakses endpoint tersebut', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 403 Forbidden", "B. 401 Unauthorized", "C. 502 Bad Gateway", "D. 201 Created", "E. 500 Internal Server Error"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 403 Forbidden!", "explanation": "Kode status HTTP `403 Forbidden` secara spesifik merepresentasikan kondisi: Client sudah terautentikasi, namun tidak memiliki hak akses (otorisasi/role) untuk mengakses endpoint tersebut."}, {"id": "SKB-PRAKOM-0095", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Multimedia & Pengolahan Citra", "q": "[Evaluasi Kompetensi Teknis Prakom #95] Format file gambar grafis berbasis vektor standar web berbasis XML yang tidak mengalami pecah (blur/pixelated) meskipun diperbesar hingga skala berapa pun adalah...", "options": ["A. BMP (Bitmap Image)", "B. GIF (Graphics Interchange Format)", "C. PNG (Portable Network Graphics)", "D. SVG (Scalable Vector Graphics)", "E. JPEG (Joint Photographic Experts Group)"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Format Vektor = SVG, EPS, AI, CDR (berbasis rumus matematis titik/kurva, tidak pecah saat di-zoom). Format Raster/Bitmap = JPEG, PNG, GIF, BMP, WEBP.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Format Vektor = SVG, EPS, AI, CDR (berbasis rumus matematis titik/kurva, tidak pecah saat di-zoom). Format Raster/Bitmap = JPEG, PNG, GIF, BMP, WEBP."}, {"id": "SKB-PRAKOM-0096", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #96:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.172.0/28`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/28` tersebut?", "options": ["A. Subnet Mask 255.255.255.240 dengan 16 usable hosts", "B. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "C. Subnet Mask 255.255.255.240 dengan 14 usable hosts (terbentuk 16 subnet dari blok /24)", "D. Subnet Mask 255.255.255.0 dengan 28 usable hosts", "E. Subnet Mask 255.255.255.240 dengan 7 usable hosts"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Untuk prefix /28: sisa bit host = 32 - 28 = 4 bit. Usable hosts = 2^4 - 2 = 14 host, dengan Subnet Mask 255.255.255.240!", "explanation": "Prefix /28 memiliki 4 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^4 = 240 (255.255.255.240), dan jumlah host valid adalah 2^4 - 2 = 14 host."}, {"id": "SKB-PRAKOM-0097", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #97), ketika terjadi kondisi di mana: 'endpoint url atau resource data yang diminta client tidak ditemukan di dalam server', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 404 Not Found", "B. 502 Bad Gateway", "C. 200 OK", "D. 201 Created", "E. 403 Forbidden"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 404 Not Found!", "explanation": "Kode status HTTP `404 Not Found` secara spesifik merepresentasikan kondisi: Endpoint URL atau resource data yang diminta client tidak ditemukan di dalam server."}, {"id": "SKB-PRAKOM-0098", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Struktur Data & Algoritma", "q": "[Evaluasi Kompetensi Teknis Prakom #98] Struktur data linier yang menerapkan prinsip LIFO (Last In, First Out) di mana elemen yang terakhir dimasukkan adalah elemen pertama yang dikeluarkan (seperti fitur Undo pada editor teks) adalah...", "options": ["A. Stack (Tumpukan)", "B. Binary Search Tree", "C. Graph Berarah", "D. Hash Table", "E. Queue (Antrean - FIFO)"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "LIFO (Last In First Out) = Stack (operasi Push & Pop). FIFO (First In First Out) = Queue (operasi Enqueue & Dequeue).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: LIFO (Last In First Out) = Stack (operasi Push & Pop). FIFO (First In First Out) = Queue (operasi Enqueue & Dequeue)."}, {"id": "SKB-PRAKOM-0099", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #99:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.193.0/29`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/29` tersebut?", "options": ["A. Subnet Mask 255.255.255.0 dengan 12 usable hosts", "B. Subnet Mask 255.255.255.248 dengan 6 usable hosts (terbentuk 32 subnet dari blok /24)", "C. Subnet Mask 255.255.255.248 dengan 8 usable hosts", "D. Subnet Mask 255.255.255.248 dengan 3 usable hosts", "E. Subnet Mask 255.255.0.0 dengan 510 usable hosts"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Untuk prefix /29: sisa bit host = 32 - 29 = 3 bit. Usable hosts = 2^3 - 2 = 6 host, dengan Subnet Mask 255.255.255.248!", "explanation": "Prefix /29 memiliki 3 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^3 = 248 (255.255.255.248), dan jumlah host valid adalah 2^3 - 2 = 6 host."}, {"id": "SKB-PRAKOM-0100", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #100), ketika terjadi kondisi di mana: 'terjadi kesalahan tak terduga pada sisi kode atau layanan backend server saat memproses permintaan', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 503 Service Unavailable", "B. 500 Internal Server Error", "C. 403 Forbidden", "D. 502 Bad Gateway", "E. 200 OK"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 500 Internal Server Error!", "explanation": "Kode status HTTP `500 Internal Server Error` secara spesifik merepresentasikan kondisi: Terjadi kesalahan tak terduga pada sisi kode atau layanan backend server saat memproses permintaan."}, {"id": "SKB-PRAKOM-0101", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Struktur Data & Algoritma", "q": "[Evaluasi Kompetensi Teknis Prakom #101] Berapakah kompleksitas waktu rata-rata (average time complexity) dari algoritma pencarian Binary Search pada sebuah array terurut berukuran $n$ elemen?", "options": ["A. O(log n)", "B. O(1)", "C. O(2^n)", "D. O(n²)", "E. O(n)"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Binary Search membagi dua ruang pencarian di setiap langkah pada data terurut, sehingga kompleksitas waktunya adalah logaritmik: O(log n).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Binary Search membagi dua ruang pencarian di setiap langkah pada data terurut, sehingga kompleksitas waktunya adalah logaritmik: O(log n)."}, {"id": "SKB-PRAKOM-0102", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #102:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.214.0/30`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/30` tersebut?", "options": ["A. Subnet Mask 255.255.255.252 dengan 4 usable hosts", "B. Subnet Mask 255.255.255.252 dengan 2 usable hosts (terbentuk 64 subnet dari blok /24)", "C. Subnet Mask 255.255.255.0 dengan 4 usable hosts", "D. Subnet Mask 255.255.255.252 dengan 2 usable hosts", "E. Subnet Mask 255.255.0.0 dengan 510 usable hosts"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Untuk prefix /30: sisa bit host = 32 - 30 = 2 bit. Usable hosts = 2^2 - 2 = 2 host, dengan Subnet Mask 255.255.255.252!", "explanation": "Prefix /30 memiliki 2 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^2 = 252 (255.255.255.252), dan jumlah host valid adalah 2^2 - 2 = 2 host."}, {"id": "SKB-PRAKOM-0103", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #103), ketika terjadi kondisi di mana: 'server yang bertindak sebagai reverse proxy atau api gateway menerima respons tidak valid dari server upstream', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 403 Forbidden", "B. 503 Service Unavailable", "C. 500 Internal Server Error", "D. 201 Created", "E. 502 Bad Gateway"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 502 Bad Gateway!", "explanation": "Kode status HTTP `502 Bad Gateway` secara spesifik merepresentasikan kondisi: Server yang bertindak sebagai reverse proxy atau API gateway menerima respons tidak valid dari server upstream."}, {"id": "SKB-PRAKOM-0104", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Pemrograman Berorientasi Objek (OOP)", "q": "[Evaluasi Kompetensi Teknis Prakom #104] Prinsip dalam Object-Oriented Programming (OOP) yang membungkus atribut data dan metode di dalam satu unit kelas serta menyembunyikan detail internal menggunakan access modifier `private` disebut...", "options": ["A. Inheritance (Pewarisan)", "B. Abstraction Interface", "C. Encapsulation (Enkapsulasi)", "D. Recursion (Rekursi)", "E. Polymorphism (Polimorfisme)"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Empat pilar OOP: 1) Encapsulation (pembungkusan & penyembunyian data private), 2) Inheritance (pewarisan sifat superclass ke subclass), 3) Polymorphism (banyak bentuk method overriding/overloading), 4) Abstraction.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Empat pilar OOP: 1) Encapsulation (pembungkusan & penyembunyian data private), 2) Inheritance (pewarisan sifat superclass ke subclass), 3) Polymorphism (banyak bentuk method overriding/overloading), 4) Abstraction."}, {"id": "SKB-PRAKOM-0105", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #105:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.235.0/24`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/24` tersebut?", "options": ["A. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "B. Subnet Mask 255.255.255.0 dengan 508 usable hosts", "C. Subnet Mask 255.255.255.0 dengan 254 usable hosts (terbentuk 1 subnet dari blok /24)", "D. Subnet Mask 255.255.255.0 dengan 256 usable hosts", "E. Subnet Mask 255.255.255.0 dengan 127 usable hosts"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Untuk prefix /24: sisa bit host = 32 - 24 = 8 bit. Usable hosts = 2^8 - 2 = 254 host, dengan Subnet Mask 255.255.255.0!", "explanation": "Prefix /24 memiliki 8 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^8 = 0 (255.255.255.0), dan jumlah host valid adalah 2^8 - 2 = 254 host."}, {"id": "SKB-PRAKOM-0106", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #106), ketika terjadi kondisi di mana: 'server sedang kelebihan beban (overload) atau sedang dalam masa pemeliharaan (maintenance) sementara', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 200 OK", "B. 503 Service Unavailable", "C. 403 Forbidden", "D. 502 Bad Gateway", "E. 400 Bad Request"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 503 Service Unavailable!", "explanation": "Kode status HTTP `503 Service Unavailable` secara spesifik merepresentasikan kondisi: Server sedang kelebihan beban (overload) atau sedang dalam masa pemeliharaan (maintenance) sementara."}, {"id": "SKB-PRAKOM-0107", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Infrastruktur Cloud Computing", "q": "[Evaluasi Kompetensi Teknis Prakom #107] Layanan komputasi awan (Cloud Computing) di mana penyedia cloud mengelola perangkat keras, jaringan, dan virtualisasi, sementara pengguna (Pranata Komputer) bertanggung jawab mengelola Sistem Operasi, Runtime, Middleware, dan Aplikasi (contoh: AWS EC2 / Google Compute Engine VM) adalah...", "options": ["A. SaaS (Software as a Service)", "B. PaaS (Platform as a Service)", "C. On-Premise Bare Metal", "D. IaaS (Infrastructure as a Service)", "E. FaaS (Function as a Service)"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Bedakan IaaS, PaaS, SaaS! IaaS = sewa VM/infrastruktur dasar (kita urus OS & aplikasi); PaaS = sewa platform siap coding (kita urus kode aplikasi & data saja); SaaS = aplikasi siap pakai (seperti Google Workspace / Microsoft 365).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Bedakan IaaS, PaaS, SaaS! IaaS = sewa VM/infrastruktur dasar (kita urus OS & aplikasi); PaaS = sewa platform siap coding (kita urus kode aplikasi & data saja); SaaS = aplikasi siap pakai (seperti Google Workspace / Microsoft 365)."}, {"id": "SKB-PRAKOM-0108", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #108:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.6.0/25`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/25` tersebut?", "options": ["A. Subnet Mask 255.255.255.128 dengan 128 usable hosts", "B. Subnet Mask 255.255.255.128 dengan 126 usable hosts (terbentuk 2 subnet dari blok /24)", "C. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "D. Subnet Mask 255.255.255.128 dengan 63 usable hosts", "E. Subnet Mask 255.255.255.0 dengan 252 usable hosts"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Untuk prefix /25: sisa bit host = 32 - 25 = 7 bit. Usable hosts = 2^7 - 2 = 126 host, dengan Subnet Mask 255.255.255.128!", "explanation": "Prefix /25 memiliki 7 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^7 = 128 (255.255.255.128), dan jumlah host valid adalah 2^7 - 2 = 126 host."}, {"id": "SKB-PRAKOM-0109", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #109), ketika terjadi kondisi di mana: 'permintaan http berhasil diproses secara normal oleh server rest api', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 400 Bad Request", "B. 201 Created", "C. 401 Unauthorized", "D. 403 Forbidden", "E. 200 OK"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 200 OK!", "explanation": "Kode status HTTP `200 OK` secara spesifik merepresentasikan kondisi: Permintaan HTTP berhasil diproses secara normal oleh server REST API."}, {"id": "SKB-PRAKOM-0110", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Protokol", "q": "[Evaluasi Kompetensi Teknis Prakom #110] Protokol jaringan yang bekerja secara otomatis mendistribusikan konfigurasi alamat IP, Subnet Mask, Default Gateway, dan DNS Server kepada komputer client di dalam jaringan lokal adalah...", "options": ["A. SNMP (Simple Network Management Protocol)", "B. DNS (Domain Name System)", "C. DHCP (Dynamic Host Configuration Protocol)", "D. ARP (Address Resolution Protocol)", "E. ICMP (Internet Control Message Protocol)"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "DHCP menggunakan proses DORA (Discover, Offer, Request, Acknowledge) untuk memberikan alamat IP secara otomatis ke host client.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: DHCP menggunakan proses DORA (Discover, Offer, Request, Acknowledge) untuk memberikan alamat IP secara otomatis ke host client."}, {"id": "SKB-PRAKOM-0111", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #111:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.27.0/26`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/26` tersebut?", "options": ["A. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "B. Subnet Mask 255.255.255.192 dengan 62 usable hosts (terbentuk 4 subnet dari blok /24)", "C. Subnet Mask 255.255.255.192 dengan 31 usable hosts", "D. Subnet Mask 255.255.255.192 dengan 64 usable hosts", "E. Subnet Mask 255.255.255.0 dengan 124 usable hosts"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Untuk prefix /26: sisa bit host = 32 - 26 = 6 bit. Usable hosts = 2^6 - 2 = 62 host, dengan Subnet Mask 255.255.255.192!", "explanation": "Prefix /26 memiliki 6 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^6 = 192 (255.255.255.192), dan jumlah host valid adalah 2^6 - 2 = 62 host."}, {"id": "SKB-PRAKOM-0112", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #112), ketika terjadi kondisi di mana: 'permintaan http post berhasil diproses dan sumber daya (resource) baru berhasil dibuat di server', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 201 Created", "B. 401 Unauthorized", "C. 403 Forbidden", "D. 503 Service Unavailable", "E. 500 Internal Server Error"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 201 Created!", "explanation": "Kode status HTTP `201 Created` secara spesifik merepresentasikan kondisi: Permintaan HTTP POST berhasil diproses dan sumber daya (resource) baru berhasil dibuat di server."}, {"id": "SKB-PRAKOM-0113", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Port Standar", "q": "[Evaluasi Kompetensi Teknis Prakom #113] Pasangan protokol jaringan dan nomor port TCP/UDP standar berikut ini yang BENAR dalam administrasi server Linux/Windows adalah...", "options": ["A. SSH (Port 22), HTTPS (Port 443), DNS (Port 53), dan HTTP (Port 80)", "B. Telnet (Port 443), RDP (Port 25), dan HTTPS (Port 8080)", "C. SSH (Port 80), HTTPS (Port 21), DNS (Port 443), dan FTP (Port 22)", "D. SMTP (Port 80), POP3 (Port 22), dan MySQL (Port 53)", "E. FTP (Port 53), SSH (Port 3306), dan PostgreSQL (Port 21)"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Hafalkan Port Penting SKB Prakom: FTP=20/21, SSH=22, Telnet=23, SMTP=25, DNS=53, DHCP=67/68, HTTP=80, POP3=110, IMAP=143, HTTPS=443, MySQL=3306, RDP=3389, PostgreSQL=5432.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Hafalkan Port Penting SKB Prakom: FTP=20/21, SSH=22, Telnet=23, SMTP=25, DNS=53, DHCP=67/68, HTTP=80, POP3=110, IMAP=143, HTTPS=443, MySQL=3306, RDP=3389, PostgreSQL=5432."}, {"id": "SKB-PRAKOM-0114", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #114:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.48.0/27`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/27` tersebut?", "options": ["A. Subnet Mask 255.255.255.224 dengan 32 usable hosts", "B. Subnet Mask 255.255.255.224 dengan 15 usable hosts", "C. Subnet Mask 255.255.255.0 dengan 60 usable hosts", "D. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "E. Subnet Mask 255.255.255.224 dengan 30 usable hosts (terbentuk 8 subnet dari blok /24)"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Untuk prefix /27: sisa bit host = 32 - 27 = 5 bit. Usable hosts = 2^5 - 2 = 30 host, dengan Subnet Mask 255.255.255.224!", "explanation": "Prefix /27 memiliki 5 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^5 = 224 (255.255.255.224), dan jumlah host valid adalah 2^5 - 2 = 30 host."}, {"id": "SKB-PRAKOM-0115", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #115), ketika terjadi kondisi di mana: 'server tidak dapat memproses permintaan karena sintaks json atau parameter input dari client tidak valid', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 502 Bad Gateway", "B. 500 Internal Server Error", "C. 401 Unauthorized", "D. 404 Not Found", "E. 400 Bad Request"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 400 Bad Request!", "explanation": "Kode status HTTP `400 Bad Request` secara spesifik merepresentasikan kondisi: Server tidak dapat memproses permintaan karena sintaks JSON atau parameter input dari client tidak valid."}, {"id": "SKB-PRAKOM-0116", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Audit TI & COBIT", "q": "[Evaluasi Kompetensi Teknis Prakom #116] Dalam pelaksanaan audit teknologi informasi pada instansi pemerintah, pemeriksaan terhadap pengendalian yang melekat pada aplikasi (seperti validasi input, pengendalian proses hitung, dan validasi output laporan) dikategorikan sebagai...", "options": ["A. IT General Control (Pengendalian Umum TI)", "B. Human Resource Administrative Control", "C. Physical Security Control", "D. Application Control (Pengendalian Aplikasi)", "E. Environmental Control"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Audit Sistem Informasi membagi pengendalian menjadi 2: 1) IT General Controls / ITGC (kebijakan keamanan umum, manajemen akses, backup, operasi pusat data), dan 2) Application Controls (Input Control, Processing Control, Output Control di dalam aplikasi).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Audit Sistem Informasi membagi pengendalian menjadi 2: 1) IT General Controls / ITGC (kebijakan keamanan umum, manajemen akses, backup, operasi pusat data), dan 2) Application Controls (Input Control, Processing Control, Output Control di dalam aplikasi)."}, {"id": "SKB-PRAKOM-0117", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #117:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.69.0/28`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/28` tersebut?", "options": ["A. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "B. Subnet Mask 255.255.255.240 dengan 16 usable hosts", "C. Subnet Mask 255.255.255.240 dengan 14 usable hosts (terbentuk 16 subnet dari blok /24)", "D. Subnet Mask 255.255.255.240 dengan 7 usable hosts", "E. Subnet Mask 255.255.255.0 dengan 28 usable hosts"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Untuk prefix /28: sisa bit host = 32 - 28 = 4 bit. Usable hosts = 2^4 - 2 = 14 host, dengan Subnet Mask 255.255.255.240!", "explanation": "Prefix /28 memiliki 4 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^4 = 240 (255.255.255.240), dan jumlah host valid adalah 2^4 - 2 = 14 host."}, {"id": "SKB-PRAKOM-0118", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #118), ketika terjadi kondisi di mana: 'permintaan ditolak karena client belum menyertakan token autentikasi (seperti jwt/bearer token) yang valid', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 201 Created", "B. 401 Unauthorized", "C. 502 Bad Gateway", "D. 403 Forbidden", "E. 200 OK"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 401 Unauthorized!", "explanation": "Kode status HTTP `401 Unauthorized` secara spesifik merepresentasikan kondisi: Permintaan ditolak karena client belum menyertakan token autentikasi (seperti JWT/Bearer Token) yang valid."}, {"id": "SKB-PRAKOM-0119", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Multimedia & Pengolahan Citra", "q": "[Evaluasi Kompetensi Teknis Prakom #119] Format file gambar grafis berbasis vektor standar web berbasis XML yang tidak mengalami pecah (blur/pixelated) meskipun diperbesar hingga skala berapa pun adalah...", "options": ["A. BMP (Bitmap Image)", "B. PNG (Portable Network Graphics)", "C. JPEG (Joint Photographic Experts Group)", "D. GIF (Graphics Interchange Format)", "E. SVG (Scalable Vector Graphics)"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Format Vektor = SVG, EPS, AI, CDR (berbasis rumus matematis titik/kurva, tidak pecah saat di-zoom). Format Raster/Bitmap = JPEG, PNG, GIF, BMP, WEBP.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Format Vektor = SVG, EPS, AI, CDR (berbasis rumus matematis titik/kurva, tidak pecah saat di-zoom). Format Raster/Bitmap = JPEG, PNG, GIF, BMP, WEBP."}, {"id": "SKB-PRAKOM-0120", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #120:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.90.0/29`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/29` tersebut?", "options": ["A. Subnet Mask 255.255.255.248 dengan 8 usable hosts", "B. Subnet Mask 255.255.255.248 dengan 3 usable hosts", "C. Subnet Mask 255.255.255.0 dengan 12 usable hosts", "D. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "E. Subnet Mask 255.255.255.248 dengan 6 usable hosts (terbentuk 32 subnet dari blok /24)"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Untuk prefix /29: sisa bit host = 32 - 29 = 3 bit. Usable hosts = 2^3 - 2 = 6 host, dengan Subnet Mask 255.255.255.248!", "explanation": "Prefix /29 memiliki 3 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^3 = 248 (255.255.255.248), dan jumlah host valid adalah 2^3 - 2 = 6 host."}, {"id": "SKB-PRAKOM-0121", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #121), ketika terjadi kondisi di mana: 'client sudah terautentikasi, namun tidak memiliki hak akses (otorisasi/role) untuk mengakses endpoint tersebut', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 503 Service Unavailable", "B. 401 Unauthorized", "C. 403 Forbidden", "D. 500 Internal Server Error", "E. 502 Bad Gateway"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 403 Forbidden!", "explanation": "Kode status HTTP `403 Forbidden` secara spesifik merepresentasikan kondisi: Client sudah terautentikasi, namun tidak memiliki hak akses (otorisasi/role) untuk mengakses endpoint tersebut."}, {"id": "SKB-PRAKOM-0122", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Struktur Data & Algoritma", "q": "[Evaluasi Kompetensi Teknis Prakom #122] Struktur data linier yang menerapkan prinsip LIFO (Last In, First Out) di mana elemen yang terakhir dimasukkan adalah elemen pertama yang dikeluarkan (seperti fitur Undo pada editor teks) adalah...", "options": ["A. Stack (Tumpukan)", "B. Queue (Antrean - FIFO)", "C. Graph Berarah", "D. Binary Search Tree", "E. Hash Table"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "LIFO (Last In First Out) = Stack (operasi Push & Pop). FIFO (First In First Out) = Queue (operasi Enqueue & Dequeue).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: LIFO (Last In First Out) = Stack (operasi Push & Pop). FIFO (First In First Out) = Queue (operasi Enqueue & Dequeue)."}, {"id": "SKB-PRAKOM-0123", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #123:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.111.0/30`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/30` tersebut?", "options": ["A. Subnet Mask 255.255.255.252 dengan 2 usable hosts (terbentuk 64 subnet dari blok /24)", "B. Subnet Mask 255.255.255.252 dengan 2 usable hosts", "C. Subnet Mask 255.255.255.0 dengan 4 usable hosts", "D. Subnet Mask 255.255.255.252 dengan 4 usable hosts", "E. Subnet Mask 255.255.0.0 dengan 510 usable hosts"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Untuk prefix /30: sisa bit host = 32 - 30 = 2 bit. Usable hosts = 2^2 - 2 = 2 host, dengan Subnet Mask 255.255.255.252!", "explanation": "Prefix /30 memiliki 2 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^2 = 252 (255.255.255.252), dan jumlah host valid adalah 2^2 - 2 = 2 host."}, {"id": "SKB-PRAKOM-0124", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #124), ketika terjadi kondisi di mana: 'endpoint url atau resource data yang diminta client tidak ditemukan di dalam server', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 404 Not Found", "B. 500 Internal Server Error", "C. 200 OK", "D. 400 Bad Request", "E. 502 Bad Gateway"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 404 Not Found!", "explanation": "Kode status HTTP `404 Not Found` secara spesifik merepresentasikan kondisi: Endpoint URL atau resource data yang diminta client tidak ditemukan di dalam server."}, {"id": "SKB-PRAKOM-0125", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Struktur Data & Algoritma", "q": "[Evaluasi Kompetensi Teknis Prakom #125] Berapakah kompleksitas waktu rata-rata (average time complexity) dari algoritma pencarian Binary Search pada sebuah array terurut berukuran $n$ elemen?", "options": ["A. O(n)", "B. O(log n)", "C. O(2^n)", "D. O(n²)", "E. O(1)"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Binary Search membagi dua ruang pencarian di setiap langkah pada data terurut, sehingga kompleksitas waktunya adalah logaritmik: O(log n).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Binary Search membagi dua ruang pencarian di setiap langkah pada data terurut, sehingga kompleksitas waktunya adalah logaritmik: O(log n)."}, {"id": "SKB-PRAKOM-0126", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #126:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.132.0/24`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/24` tersebut?", "options": ["A. Subnet Mask 255.255.255.0 dengan 256 usable hosts", "B. Subnet Mask 255.255.255.0 dengan 254 usable hosts (terbentuk 1 subnet dari blok /24)", "C. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "D. Subnet Mask 255.255.255.0 dengan 508 usable hosts", "E. Subnet Mask 255.255.255.0 dengan 127 usable hosts"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Untuk prefix /24: sisa bit host = 32 - 24 = 8 bit. Usable hosts = 2^8 - 2 = 254 host, dengan Subnet Mask 255.255.255.0!", "explanation": "Prefix /24 memiliki 8 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^8 = 0 (255.255.255.0), dan jumlah host valid adalah 2^8 - 2 = 254 host."}, {"id": "SKB-PRAKOM-0127", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #127), ketika terjadi kondisi di mana: 'terjadi kesalahan tak terduga pada sisi kode atau layanan backend server saat memproses permintaan', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 500 Internal Server Error", "B. 404 Not Found", "C. 403 Forbidden", "D. 200 OK", "E. 502 Bad Gateway"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 500 Internal Server Error!", "explanation": "Kode status HTTP `500 Internal Server Error` secara spesifik merepresentasikan kondisi: Terjadi kesalahan tak terduga pada sisi kode atau layanan backend server saat memproses permintaan."}, {"id": "SKB-PRAKOM-0128", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Pemrograman Berorientasi Objek (OOP)", "q": "[Evaluasi Kompetensi Teknis Prakom #128] Prinsip dalam Object-Oriented Programming (OOP) yang membungkus atribut data dan metode di dalam satu unit kelas serta menyembunyikan detail internal menggunakan access modifier `private` disebut...", "options": ["A. Encapsulation (Enkapsulasi)", "B. Abstraction Interface", "C. Recursion (Rekursi)", "D. Inheritance (Pewarisan)", "E. Polymorphism (Polimorfisme)"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Empat pilar OOP: 1) Encapsulation (pembungkusan & penyembunyian data private), 2) Inheritance (pewarisan sifat superclass ke subclass), 3) Polymorphism (banyak bentuk method overriding/overloading), 4) Abstraction.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Empat pilar OOP: 1) Encapsulation (pembungkusan & penyembunyian data private), 2) Inheritance (pewarisan sifat superclass ke subclass), 3) Polymorphism (banyak bentuk method overriding/overloading), 4) Abstraction."}, {"id": "SKB-PRAKOM-0129", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #129:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.153.0/25`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/25` tersebut?", "options": ["A. Subnet Mask 255.255.255.128 dengan 126 usable hosts (terbentuk 2 subnet dari blok /24)", "B. Subnet Mask 255.255.255.0 dengan 252 usable hosts", "C. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "D. Subnet Mask 255.255.255.128 dengan 63 usable hosts", "E. Subnet Mask 255.255.255.128 dengan 128 usable hosts"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Untuk prefix /25: sisa bit host = 32 - 25 = 7 bit. Usable hosts = 2^7 - 2 = 126 host, dengan Subnet Mask 255.255.255.128!", "explanation": "Prefix /25 memiliki 7 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^7 = 128 (255.255.255.128), dan jumlah host valid adalah 2^7 - 2 = 126 host."}, {"id": "SKB-PRAKOM-0130", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #130), ketika terjadi kondisi di mana: 'server yang bertindak sebagai reverse proxy atau api gateway menerima respons tidak valid dari server upstream', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 403 Forbidden", "B. 502 Bad Gateway", "C. 400 Bad Request", "D. 500 Internal Server Error", "E. 200 OK"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 502 Bad Gateway!", "explanation": "Kode status HTTP `502 Bad Gateway` secara spesifik merepresentasikan kondisi: Server yang bertindak sebagai reverse proxy atau API gateway menerima respons tidak valid dari server upstream."}, {"id": "SKB-PRAKOM-0131", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Infrastruktur Cloud Computing", "q": "[Evaluasi Kompetensi Teknis Prakom #131] Layanan komputasi awan (Cloud Computing) di mana penyedia cloud mengelola perangkat keras, jaringan, dan virtualisasi, sementara pengguna (Pranata Komputer) bertanggung jawab mengelola Sistem Operasi, Runtime, Middleware, dan Aplikasi (contoh: AWS EC2 / Google Compute Engine VM) adalah...", "options": ["A. IaaS (Infrastructure as a Service)", "B. PaaS (Platform as a Service)", "C. SaaS (Software as a Service)", "D. FaaS (Function as a Service)", "E. On-Premise Bare Metal"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Bedakan IaaS, PaaS, SaaS! IaaS = sewa VM/infrastruktur dasar (kita urus OS & aplikasi); PaaS = sewa platform siap coding (kita urus kode aplikasi & data saja); SaaS = aplikasi siap pakai (seperti Google Workspace / Microsoft 365).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Bedakan IaaS, PaaS, SaaS! IaaS = sewa VM/infrastruktur dasar (kita urus OS & aplikasi); PaaS = sewa platform siap coding (kita urus kode aplikasi & data saja); SaaS = aplikasi siap pakai (seperti Google Workspace / Microsoft 365)."}, {"id": "SKB-PRAKOM-0132", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #132:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.174.0/26`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/26` tersebut?", "options": ["A. Subnet Mask 255.255.255.192 dengan 31 usable hosts", "B. Subnet Mask 255.255.255.192 dengan 64 usable hosts", "C. Subnet Mask 255.255.255.192 dengan 62 usable hosts (terbentuk 4 subnet dari blok /24)", "D. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "E. Subnet Mask 255.255.255.0 dengan 124 usable hosts"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Untuk prefix /26: sisa bit host = 32 - 26 = 6 bit. Usable hosts = 2^6 - 2 = 62 host, dengan Subnet Mask 255.255.255.192!", "explanation": "Prefix /26 memiliki 6 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^6 = 192 (255.255.255.192), dan jumlah host valid adalah 2^6 - 2 = 62 host."}, {"id": "SKB-PRAKOM-0133", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #133), ketika terjadi kondisi di mana: 'server sedang kelebihan beban (overload) atau sedang dalam masa pemeliharaan (maintenance) sementara', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 200 OK", "B. 500 Internal Server Error", "C. 503 Service Unavailable", "D. 201 Created", "E. 401 Unauthorized"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 503 Service Unavailable!", "explanation": "Kode status HTTP `503 Service Unavailable` secara spesifik merepresentasikan kondisi: Server sedang kelebihan beban (overload) atau sedang dalam masa pemeliharaan (maintenance) sementara."}, {"id": "SKB-PRAKOM-0134", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Protokol", "q": "[Evaluasi Kompetensi Teknis Prakom #134] Protokol jaringan yang bekerja secara otomatis mendistribusikan konfigurasi alamat IP, Subnet Mask, Default Gateway, dan DNS Server kepada komputer client di dalam jaringan lokal adalah...", "options": ["A. ARP (Address Resolution Protocol)", "B. DHCP (Dynamic Host Configuration Protocol)", "C. ICMP (Internet Control Message Protocol)", "D. SNMP (Simple Network Management Protocol)", "E. DNS (Domain Name System)"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "DHCP menggunakan proses DORA (Discover, Offer, Request, Acknowledge) untuk memberikan alamat IP secara otomatis ke host client.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: DHCP menggunakan proses DORA (Discover, Offer, Request, Acknowledge) untuk memberikan alamat IP secara otomatis ke host client."}, {"id": "SKB-PRAKOM-0135", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #135:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.195.0/27`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/27` tersebut?", "options": ["A. Subnet Mask 255.255.255.0 dengan 60 usable hosts", "B. Subnet Mask 255.255.255.224 dengan 15 usable hosts", "C. Subnet Mask 255.255.255.224 dengan 32 usable hosts", "D. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "E. Subnet Mask 255.255.255.224 dengan 30 usable hosts (terbentuk 8 subnet dari blok /24)"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Untuk prefix /27: sisa bit host = 32 - 27 = 5 bit. Usable hosts = 2^5 - 2 = 30 host, dengan Subnet Mask 255.255.255.224!", "explanation": "Prefix /27 memiliki 5 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^5 = 224 (255.255.255.224), dan jumlah host valid adalah 2^5 - 2 = 30 host."}, {"id": "SKB-PRAKOM-0136", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #136), ketika terjadi kondisi di mana: 'permintaan http berhasil diproses secara normal oleh server rest api', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 201 Created", "B. 403 Forbidden", "C. 502 Bad Gateway", "D. 404 Not Found", "E. 200 OK"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 200 OK!", "explanation": "Kode status HTTP `200 OK` secara spesifik merepresentasikan kondisi: Permintaan HTTP berhasil diproses secara normal oleh server REST API."}, {"id": "SKB-PRAKOM-0137", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Port Standar", "q": "[Evaluasi Kompetensi Teknis Prakom #137] Pasangan protokol jaringan dan nomor port TCP/UDP standar berikut ini yang BENAR dalam administrasi server Linux/Windows adalah...", "options": ["A. Telnet (Port 443), RDP (Port 25), dan HTTPS (Port 8080)", "B. SSH (Port 80), HTTPS (Port 21), DNS (Port 443), dan FTP (Port 22)", "C. SSH (Port 22), HTTPS (Port 443), DNS (Port 53), dan HTTP (Port 80)", "D. SMTP (Port 80), POP3 (Port 22), dan MySQL (Port 53)", "E. FTP (Port 53), SSH (Port 3306), dan PostgreSQL (Port 21)"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Hafalkan Port Penting SKB Prakom: FTP=20/21, SSH=22, Telnet=23, SMTP=25, DNS=53, DHCP=67/68, HTTP=80, POP3=110, IMAP=143, HTTPS=443, MySQL=3306, RDP=3389, PostgreSQL=5432.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Hafalkan Port Penting SKB Prakom: FTP=20/21, SSH=22, Telnet=23, SMTP=25, DNS=53, DHCP=67/68, HTTP=80, POP3=110, IMAP=143, HTTPS=443, MySQL=3306, RDP=3389, PostgreSQL=5432."}, {"id": "SKB-PRAKOM-0138", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #138:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.216.0/28`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/28` tersebut?", "options": ["A. Subnet Mask 255.255.255.240 dengan 7 usable hosts", "B. Subnet Mask 255.255.255.0 dengan 28 usable hosts", "C. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "D. Subnet Mask 255.255.255.240 dengan 14 usable hosts (terbentuk 16 subnet dari blok /24)", "E. Subnet Mask 255.255.255.240 dengan 16 usable hosts"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Untuk prefix /28: sisa bit host = 32 - 28 = 4 bit. Usable hosts = 2^4 - 2 = 14 host, dengan Subnet Mask 255.255.255.240!", "explanation": "Prefix /28 memiliki 4 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^4 = 240 (255.255.255.240), dan jumlah host valid adalah 2^4 - 2 = 14 host."}, {"id": "SKB-PRAKOM-0139", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #139), ketika terjadi kondisi di mana: 'permintaan http post berhasil diproses dan sumber daya (resource) baru berhasil dibuat di server', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 503 Service Unavailable", "B. 404 Not Found", "C. 201 Created", "D. 502 Bad Gateway", "E. 403 Forbidden"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 201 Created!", "explanation": "Kode status HTTP `201 Created` secara spesifik merepresentasikan kondisi: Permintaan HTTP POST berhasil diproses dan sumber daya (resource) baru berhasil dibuat di server."}, {"id": "SKB-PRAKOM-0140", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Audit TI & COBIT", "q": "[Evaluasi Kompetensi Teknis Prakom #140] Dalam pelaksanaan audit teknologi informasi pada instansi pemerintah, pemeriksaan terhadap pengendalian yang melekat pada aplikasi (seperti validasi input, pengendalian proses hitung, dan validasi output laporan) dikategorikan sebagai...", "options": ["A. Physical Security Control", "B. Application Control (Pengendalian Aplikasi)", "C. IT General Control (Pengendalian Umum TI)", "D. Human Resource Administrative Control", "E. Environmental Control"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Audit Sistem Informasi membagi pengendalian menjadi 2: 1) IT General Controls / ITGC (kebijakan keamanan umum, manajemen akses, backup, operasi pusat data), dan 2) Application Controls (Input Control, Processing Control, Output Control di dalam aplikasi).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Audit Sistem Informasi membagi pengendalian menjadi 2: 1) IT General Controls / ITGC (kebijakan keamanan umum, manajemen akses, backup, operasi pusat data), dan 2) Application Controls (Input Control, Processing Control, Output Control di dalam aplikasi)."}, {"id": "SKB-PRAKOM-0141", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #141:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.237.0/29`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/29` tersebut?", "options": ["A. Subnet Mask 255.255.255.248 dengan 3 usable hosts", "B. Subnet Mask 255.255.255.0 dengan 12 usable hosts", "C. Subnet Mask 255.255.255.248 dengan 6 usable hosts (terbentuk 32 subnet dari blok /24)", "D. Subnet Mask 255.255.255.248 dengan 8 usable hosts", "E. Subnet Mask 255.255.0.0 dengan 510 usable hosts"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Untuk prefix /29: sisa bit host = 32 - 29 = 3 bit. Usable hosts = 2^3 - 2 = 6 host, dengan Subnet Mask 255.255.255.248!", "explanation": "Prefix /29 memiliki 3 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^3 = 248 (255.255.255.248), dan jumlah host valid adalah 2^3 - 2 = 6 host."}, {"id": "SKB-PRAKOM-0142", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #142), ketika terjadi kondisi di mana: 'server tidak dapat memproses permintaan karena sintaks json atau parameter input dari client tidak valid', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 404 Not Found", "B. 503 Service Unavailable", "C. 403 Forbidden", "D. 201 Created", "E. 400 Bad Request"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 400 Bad Request!", "explanation": "Kode status HTTP `400 Bad Request` secara spesifik merepresentasikan kondisi: Server tidak dapat memproses permintaan karena sintaks JSON atau parameter input dari client tidak valid."}, {"id": "SKB-PRAKOM-0143", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Multimedia & Pengolahan Citra", "q": "[Evaluasi Kompetensi Teknis Prakom #143] Format file gambar grafis berbasis vektor standar web berbasis XML yang tidak mengalami pecah (blur/pixelated) meskipun diperbesar hingga skala berapa pun adalah...", "options": ["A. JPEG (Joint Photographic Experts Group)", "B. GIF (Graphics Interchange Format)", "C. PNG (Portable Network Graphics)", "D. SVG (Scalable Vector Graphics)", "E. BMP (Bitmap Image)"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Format Vektor = SVG, EPS, AI, CDR (berbasis rumus matematis titik/kurva, tidak pecah saat di-zoom). Format Raster/Bitmap = JPEG, PNG, GIF, BMP, WEBP.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Format Vektor = SVG, EPS, AI, CDR (berbasis rumus matematis titik/kurva, tidak pecah saat di-zoom). Format Raster/Bitmap = JPEG, PNG, GIF, BMP, WEBP."}, {"id": "SKB-PRAKOM-0144", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #144:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.8.0/30`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/30` tersebut?", "options": ["A. Subnet Mask 255.255.255.252 dengan 2 usable hosts (terbentuk 64 subnet dari blok /24)", "B. Subnet Mask 255.255.255.0 dengan 4 usable hosts", "C. Subnet Mask 255.255.255.252 dengan 4 usable hosts", "D. Subnet Mask 255.255.255.252 dengan 2 usable hosts", "E. Subnet Mask 255.255.0.0 dengan 510 usable hosts"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Untuk prefix /30: sisa bit host = 32 - 30 = 2 bit. Usable hosts = 2^2 - 2 = 2 host, dengan Subnet Mask 255.255.255.252!", "explanation": "Prefix /30 memiliki 2 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^2 = 252 (255.255.255.252), dan jumlah host valid adalah 2^2 - 2 = 2 host."}, {"id": "SKB-PRAKOM-0145", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #145), ketika terjadi kondisi di mana: 'permintaan ditolak karena client belum menyertakan token autentikasi (seperti jwt/bearer token) yang valid', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 201 Created", "B. 403 Forbidden", "C. 502 Bad Gateway", "D. 401 Unauthorized", "E. 200 OK"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 401 Unauthorized!", "explanation": "Kode status HTTP `401 Unauthorized` secara spesifik merepresentasikan kondisi: Permintaan ditolak karena client belum menyertakan token autentikasi (seperti JWT/Bearer Token) yang valid."}, {"id": "SKB-PRAKOM-0146", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Struktur Data & Algoritma", "q": "[Evaluasi Kompetensi Teknis Prakom #146] Struktur data linier yang menerapkan prinsip LIFO (Last In, First Out) di mana elemen yang terakhir dimasukkan adalah elemen pertama yang dikeluarkan (seperti fitur Undo pada editor teks) adalah...", "options": ["A. Queue (Antrean - FIFO)", "B. Hash Table", "C. Binary Search Tree", "D. Graph Berarah", "E. Stack (Tumpukan)"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "LIFO (Last In First Out) = Stack (operasi Push & Pop). FIFO (First In First Out) = Queue (operasi Enqueue & Dequeue).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: LIFO (Last In First Out) = Stack (operasi Push & Pop). FIFO (First In First Out) = Queue (operasi Enqueue & Dequeue)."}, {"id": "SKB-PRAKOM-0147", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #147:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.29.0/24`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/24` tersebut?", "options": ["A. Subnet Mask 255.255.255.0 dengan 508 usable hosts", "B. Subnet Mask 255.255.255.0 dengan 256 usable hosts", "C. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "D. Subnet Mask 255.255.255.0 dengan 254 usable hosts (terbentuk 1 subnet dari blok /24)", "E. Subnet Mask 255.255.255.0 dengan 127 usable hosts"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Untuk prefix /24: sisa bit host = 32 - 24 = 8 bit. Usable hosts = 2^8 - 2 = 254 host, dengan Subnet Mask 255.255.255.0!", "explanation": "Prefix /24 memiliki 8 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^8 = 0 (255.255.255.0), dan jumlah host valid adalah 2^8 - 2 = 254 host."}, {"id": "SKB-PRAKOM-0148", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #148), ketika terjadi kondisi di mana: 'client sudah terautentikasi, namun tidak memiliki hak akses (otorisasi/role) untuk mengakses endpoint tersebut', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 503 Service Unavailable", "B. 200 OK", "C. 404 Not Found", "D. 201 Created", "E. 403 Forbidden"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 403 Forbidden!", "explanation": "Kode status HTTP `403 Forbidden` secara spesifik merepresentasikan kondisi: Client sudah terautentikasi, namun tidak memiliki hak akses (otorisasi/role) untuk mengakses endpoint tersebut."}, {"id": "SKB-PRAKOM-0149", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Struktur Data & Algoritma", "q": "[Evaluasi Kompetensi Teknis Prakom #149] Berapakah kompleksitas waktu rata-rata (average time complexity) dari algoritma pencarian Binary Search pada sebuah array terurut berukuran $n$ elemen?", "options": ["A. O(n)", "B. O(1)", "C. O(n²)", "D. O(log n)", "E. O(2^n)"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Binary Search membagi dua ruang pencarian di setiap langkah pada data terurut, sehingga kompleksitas waktunya adalah logaritmik: O(log n).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Binary Search membagi dua ruang pencarian di setiap langkah pada data terurut, sehingga kompleksitas waktunya adalah logaritmik: O(log n)."}, {"id": "SKB-PRAKOM-0150", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #150:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.50.0/25`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/25` tersebut?", "options": ["A. Subnet Mask 255.255.255.128 dengan 128 usable hosts", "B. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "C. Subnet Mask 255.255.255.0 dengan 252 usable hosts", "D. Subnet Mask 255.255.255.128 dengan 63 usable hosts", "E. Subnet Mask 255.255.255.128 dengan 126 usable hosts (terbentuk 2 subnet dari blok /24)"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Untuk prefix /25: sisa bit host = 32 - 25 = 7 bit. Usable hosts = 2^7 - 2 = 126 host, dengan Subnet Mask 255.255.255.128!", "explanation": "Prefix /25 memiliki 7 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^7 = 128 (255.255.255.128), dan jumlah host valid adalah 2^7 - 2 = 126 host."}, {"id": "SKB-PRAKOM-0151", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #151), ketika terjadi kondisi di mana: 'endpoint url atau resource data yang diminta client tidak ditemukan di dalam server', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 503 Service Unavailable", "B. 500 Internal Server Error", "C. 404 Not Found", "D. 401 Unauthorized", "E. 200 OK"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 404 Not Found!", "explanation": "Kode status HTTP `404 Not Found` secara spesifik merepresentasikan kondisi: Endpoint URL atau resource data yang diminta client tidak ditemukan di dalam server."}, {"id": "SKB-PRAKOM-0152", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Pemrograman Berorientasi Objek (OOP)", "q": "[Evaluasi Kompetensi Teknis Prakom #152] Prinsip dalam Object-Oriented Programming (OOP) yang membungkus atribut data dan metode di dalam satu unit kelas serta menyembunyikan detail internal menggunakan access modifier `private` disebut...", "options": ["A. Inheritance (Pewarisan)", "B. Polymorphism (Polimorfisme)", "C. Recursion (Rekursi)", "D. Abstraction Interface", "E. Encapsulation (Enkapsulasi)"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Empat pilar OOP: 1) Encapsulation (pembungkusan & penyembunyian data private), 2) Inheritance (pewarisan sifat superclass ke subclass), 3) Polymorphism (banyak bentuk method overriding/overloading), 4) Abstraction.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Empat pilar OOP: 1) Encapsulation (pembungkusan & penyembunyian data private), 2) Inheritance (pewarisan sifat superclass ke subclass), 3) Polymorphism (banyak bentuk method overriding/overloading), 4) Abstraction."}, {"id": "SKB-PRAKOM-0153", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #153:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.71.0/26`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/26` tersebut?", "options": ["A. Subnet Mask 255.255.255.0 dengan 124 usable hosts", "B. Subnet Mask 255.255.255.192 dengan 64 usable hosts", "C. Subnet Mask 255.255.255.192 dengan 62 usable hosts (terbentuk 4 subnet dari blok /24)", "D. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "E. Subnet Mask 255.255.255.192 dengan 31 usable hosts"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Untuk prefix /26: sisa bit host = 32 - 26 = 6 bit. Usable hosts = 2^6 - 2 = 62 host, dengan Subnet Mask 255.255.255.192!", "explanation": "Prefix /26 memiliki 6 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^6 = 192 (255.255.255.192), dan jumlah host valid adalah 2^6 - 2 = 62 host."}, {"id": "SKB-PRAKOM-0154", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #154), ketika terjadi kondisi di mana: 'terjadi kesalahan tak terduga pada sisi kode atau layanan backend server saat memproses permintaan', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 201 Created", "B. 401 Unauthorized", "C. 200 OK", "D. 404 Not Found", "E. 500 Internal Server Error"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 500 Internal Server Error!", "explanation": "Kode status HTTP `500 Internal Server Error` secara spesifik merepresentasikan kondisi: Terjadi kesalahan tak terduga pada sisi kode atau layanan backend server saat memproses permintaan."}, {"id": "SKB-PRAKOM-0155", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Infrastruktur Cloud Computing", "q": "[Evaluasi Kompetensi Teknis Prakom #155] Layanan komputasi awan (Cloud Computing) di mana penyedia cloud mengelola perangkat keras, jaringan, dan virtualisasi, sementara pengguna (Pranata Komputer) bertanggung jawab mengelola Sistem Operasi, Runtime, Middleware, dan Aplikasi (contoh: AWS EC2 / Google Compute Engine VM) adalah...", "options": ["A. IaaS (Infrastructure as a Service)", "B. FaaS (Function as a Service)", "C. PaaS (Platform as a Service)", "D. SaaS (Software as a Service)", "E. On-Premise Bare Metal"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Bedakan IaaS, PaaS, SaaS! IaaS = sewa VM/infrastruktur dasar (kita urus OS & aplikasi); PaaS = sewa platform siap coding (kita urus kode aplikasi & data saja); SaaS = aplikasi siap pakai (seperti Google Workspace / Microsoft 365).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Bedakan IaaS, PaaS, SaaS! IaaS = sewa VM/infrastruktur dasar (kita urus OS & aplikasi); PaaS = sewa platform siap coding (kita urus kode aplikasi & data saja); SaaS = aplikasi siap pakai (seperti Google Workspace / Microsoft 365)."}, {"id": "SKB-PRAKOM-0156", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #156:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.92.0/27`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/27` tersebut?", "options": ["A. Subnet Mask 255.255.255.0 dengan 60 usable hosts", "B. Subnet Mask 255.255.255.224 dengan 15 usable hosts", "C. Subnet Mask 255.255.255.224 dengan 32 usable hosts", "D. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "E. Subnet Mask 255.255.255.224 dengan 30 usable hosts (terbentuk 8 subnet dari blok /24)"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Untuk prefix /27: sisa bit host = 32 - 27 = 5 bit. Usable hosts = 2^5 - 2 = 30 host, dengan Subnet Mask 255.255.255.224!", "explanation": "Prefix /27 memiliki 5 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^5 = 224 (255.255.255.224), dan jumlah host valid adalah 2^5 - 2 = 30 host."}, {"id": "SKB-PRAKOM-0157", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #157), ketika terjadi kondisi di mana: 'server yang bertindak sebagai reverse proxy atau api gateway menerima respons tidak valid dari server upstream', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 400 Bad Request", "B. 201 Created", "C. 503 Service Unavailable", "D. 502 Bad Gateway", "E. 500 Internal Server Error"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 502 Bad Gateway!", "explanation": "Kode status HTTP `502 Bad Gateway` secara spesifik merepresentasikan kondisi: Server yang bertindak sebagai reverse proxy atau API gateway menerima respons tidak valid dari server upstream."}, {"id": "SKB-PRAKOM-0158", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Protokol", "q": "[Evaluasi Kompetensi Teknis Prakom #158] Protokol jaringan yang bekerja secara otomatis mendistribusikan konfigurasi alamat IP, Subnet Mask, Default Gateway, dan DNS Server kepada komputer client di dalam jaringan lokal adalah...", "options": ["A. DNS (Domain Name System)", "B. DHCP (Dynamic Host Configuration Protocol)", "C. SNMP (Simple Network Management Protocol)", "D. ICMP (Internet Control Message Protocol)", "E. ARP (Address Resolution Protocol)"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "DHCP menggunakan proses DORA (Discover, Offer, Request, Acknowledge) untuk memberikan alamat IP secara otomatis ke host client.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: DHCP menggunakan proses DORA (Discover, Offer, Request, Acknowledge) untuk memberikan alamat IP secara otomatis ke host client."}, {"id": "SKB-PRAKOM-0159", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #159:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.113.0/28`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/28` tersebut?", "options": ["A. Subnet Mask 255.255.255.0 dengan 28 usable hosts", "B. Subnet Mask 255.255.255.240 dengan 7 usable hosts", "C. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "D. Subnet Mask 255.255.255.240 dengan 16 usable hosts", "E. Subnet Mask 255.255.255.240 dengan 14 usable hosts (terbentuk 16 subnet dari blok /24)"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Untuk prefix /28: sisa bit host = 32 - 28 = 4 bit. Usable hosts = 2^4 - 2 = 14 host, dengan Subnet Mask 255.255.255.240!", "explanation": "Prefix /28 memiliki 4 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^4 = 240 (255.255.255.240), dan jumlah host valid adalah 2^4 - 2 = 14 host."}, {"id": "SKB-PRAKOM-0160", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #160), ketika terjadi kondisi di mana: 'server sedang kelebihan beban (overload) atau sedang dalam masa pemeliharaan (maintenance) sementara', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 200 OK", "B. 201 Created", "C. 503 Service Unavailable", "D. 403 Forbidden", "E. 502 Bad Gateway"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 503 Service Unavailable!", "explanation": "Kode status HTTP `503 Service Unavailable` secara spesifik merepresentasikan kondisi: Server sedang kelebihan beban (overload) atau sedang dalam masa pemeliharaan (maintenance) sementara."}, {"id": "SKB-PRAKOM-0161", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Port Standar", "q": "[Evaluasi Kompetensi Teknis Prakom #161] Pasangan protokol jaringan dan nomor port TCP/UDP standar berikut ini yang BENAR dalam administrasi server Linux/Windows adalah...", "options": ["A. SSH (Port 80), HTTPS (Port 21), DNS (Port 443), dan FTP (Port 22)", "B. FTP (Port 53), SSH (Port 3306), dan PostgreSQL (Port 21)", "C. SSH (Port 22), HTTPS (Port 443), DNS (Port 53), dan HTTP (Port 80)", "D. Telnet (Port 443), RDP (Port 25), dan HTTPS (Port 8080)", "E. SMTP (Port 80), POP3 (Port 22), dan MySQL (Port 53)"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Hafalkan Port Penting SKB Prakom: FTP=20/21, SSH=22, Telnet=23, SMTP=25, DNS=53, DHCP=67/68, HTTP=80, POP3=110, IMAP=143, HTTPS=443, MySQL=3306, RDP=3389, PostgreSQL=5432.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Hafalkan Port Penting SKB Prakom: FTP=20/21, SSH=22, Telnet=23, SMTP=25, DNS=53, DHCP=67/68, HTTP=80, POP3=110, IMAP=143, HTTPS=443, MySQL=3306, RDP=3389, PostgreSQL=5432."}, {"id": "SKB-PRAKOM-0162", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #162:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.134.0/29`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/29` tersebut?", "options": ["A. Subnet Mask 255.255.255.248 dengan 6 usable hosts (terbentuk 32 subnet dari blok /24)", "B. Subnet Mask 255.255.255.248 dengan 8 usable hosts", "C. Subnet Mask 255.255.255.248 dengan 3 usable hosts", "D. Subnet Mask 255.255.255.0 dengan 12 usable hosts", "E. Subnet Mask 255.255.0.0 dengan 510 usable hosts"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Untuk prefix /29: sisa bit host = 32 - 29 = 3 bit. Usable hosts = 2^3 - 2 = 6 host, dengan Subnet Mask 255.255.255.248!", "explanation": "Prefix /29 memiliki 3 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^3 = 248 (255.255.255.248), dan jumlah host valid adalah 2^3 - 2 = 6 host."}, {"id": "SKB-PRAKOM-0163", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #163), ketika terjadi kondisi di mana: 'permintaan http berhasil diproses secara normal oleh server rest api', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 502 Bad Gateway", "B. 201 Created", "C. 503 Service Unavailable", "D. 200 OK", "E. 500 Internal Server Error"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 200 OK!", "explanation": "Kode status HTTP `200 OK` secara spesifik merepresentasikan kondisi: Permintaan HTTP berhasil diproses secara normal oleh server REST API."}, {"id": "SKB-PRAKOM-0164", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Audit TI & COBIT", "q": "[Evaluasi Kompetensi Teknis Prakom #164] Dalam pelaksanaan audit teknologi informasi pada instansi pemerintah, pemeriksaan terhadap pengendalian yang melekat pada aplikasi (seperti validasi input, pengendalian proses hitung, dan validasi output laporan) dikategorikan sebagai...", "options": ["A. IT General Control (Pengendalian Umum TI)", "B. Human Resource Administrative Control", "C. Application Control (Pengendalian Aplikasi)", "D. Environmental Control", "E. Physical Security Control"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Audit Sistem Informasi membagi pengendalian menjadi 2: 1) IT General Controls / ITGC (kebijakan keamanan umum, manajemen akses, backup, operasi pusat data), dan 2) Application Controls (Input Control, Processing Control, Output Control di dalam aplikasi).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Audit Sistem Informasi membagi pengendalian menjadi 2: 1) IT General Controls / ITGC (kebijakan keamanan umum, manajemen akses, backup, operasi pusat data), dan 2) Application Controls (Input Control, Processing Control, Output Control di dalam aplikasi)."}, {"id": "SKB-PRAKOM-0165", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #165:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.155.0/30`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/30` tersebut?", "options": ["A. Subnet Mask 255.255.255.252 dengan 2 usable hosts", "B. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "C. Subnet Mask 255.255.255.0 dengan 4 usable hosts", "D. Subnet Mask 255.255.255.252 dengan 4 usable hosts", "E. Subnet Mask 255.255.255.252 dengan 2 usable hosts (terbentuk 64 subnet dari blok /24)"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Untuk prefix /30: sisa bit host = 32 - 30 = 2 bit. Usable hosts = 2^2 - 2 = 2 host, dengan Subnet Mask 255.255.255.252!", "explanation": "Prefix /30 memiliki 2 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^2 = 252 (255.255.255.252), dan jumlah host valid adalah 2^2 - 2 = 2 host."}, {"id": "SKB-PRAKOM-0166", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #166), ketika terjadi kondisi di mana: 'permintaan http post berhasil diproses dan sumber daya (resource) baru berhasil dibuat di server', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 500 Internal Server Error", "B. 400 Bad Request", "C. 503 Service Unavailable", "D. 502 Bad Gateway", "E. 201 Created"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 201 Created!", "explanation": "Kode status HTTP `201 Created` secara spesifik merepresentasikan kondisi: Permintaan HTTP POST berhasil diproses dan sumber daya (resource) baru berhasil dibuat di server."}, {"id": "SKB-PRAKOM-0167", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Multimedia & Pengolahan Citra", "q": "[Evaluasi Kompetensi Teknis Prakom #167] Format file gambar grafis berbasis vektor standar web berbasis XML yang tidak mengalami pecah (blur/pixelated) meskipun diperbesar hingga skala berapa pun adalah...", "options": ["A. PNG (Portable Network Graphics)", "B. SVG (Scalable Vector Graphics)", "C. JPEG (Joint Photographic Experts Group)", "D. GIF (Graphics Interchange Format)", "E. BMP (Bitmap Image)"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Format Vektor = SVG, EPS, AI, CDR (berbasis rumus matematis titik/kurva, tidak pecah saat di-zoom). Format Raster/Bitmap = JPEG, PNG, GIF, BMP, WEBP.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Format Vektor = SVG, EPS, AI, CDR (berbasis rumus matematis titik/kurva, tidak pecah saat di-zoom). Format Raster/Bitmap = JPEG, PNG, GIF, BMP, WEBP."}, {"id": "SKB-PRAKOM-0168", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #168:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.176.0/24`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/24` tersebut?", "options": ["A. Subnet Mask 255.255.255.0 dengan 127 usable hosts", "B. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "C. Subnet Mask 255.255.255.0 dengan 508 usable hosts", "D. Subnet Mask 255.255.255.0 dengan 256 usable hosts", "E. Subnet Mask 255.255.255.0 dengan 254 usable hosts (terbentuk 1 subnet dari blok /24)"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Untuk prefix /24: sisa bit host = 32 - 24 = 8 bit. Usable hosts = 2^8 - 2 = 254 host, dengan Subnet Mask 255.255.255.0!", "explanation": "Prefix /24 memiliki 8 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^8 = 0 (255.255.255.0), dan jumlah host valid adalah 2^8 - 2 = 254 host."}, {"id": "SKB-PRAKOM-0169", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #169), ketika terjadi kondisi di mana: 'server tidak dapat memproses permintaan karena sintaks json atau parameter input dari client tidak valid', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 400 Bad Request", "B. 401 Unauthorized", "C. 503 Service Unavailable", "D. 500 Internal Server Error", "E. 200 OK"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 400 Bad Request!", "explanation": "Kode status HTTP `400 Bad Request` secara spesifik merepresentasikan kondisi: Server tidak dapat memproses permintaan karena sintaks JSON atau parameter input dari client tidak valid."}, {"id": "SKB-PRAKOM-0170", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Struktur Data & Algoritma", "q": "[Evaluasi Kompetensi Teknis Prakom #170] Struktur data linier yang menerapkan prinsip LIFO (Last In, First Out) di mana elemen yang terakhir dimasukkan adalah elemen pertama yang dikeluarkan (seperti fitur Undo pada editor teks) adalah...", "options": ["A. Queue (Antrean - FIFO)", "B. Graph Berarah", "C. Stack (Tumpukan)", "D. Hash Table", "E. Binary Search Tree"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "LIFO (Last In First Out) = Stack (operasi Push & Pop). FIFO (First In First Out) = Queue (operasi Enqueue & Dequeue).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: LIFO (Last In First Out) = Stack (operasi Push & Pop). FIFO (First In First Out) = Queue (operasi Enqueue & Dequeue)."}, {"id": "SKB-PRAKOM-0171", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #171:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.197.0/25`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/25` tersebut?", "options": ["A. Subnet Mask 255.255.255.128 dengan 126 usable hosts (terbentuk 2 subnet dari blok /24)", "B. Subnet Mask 255.255.255.0 dengan 252 usable hosts", "C. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "D. Subnet Mask 255.255.255.128 dengan 128 usable hosts", "E. Subnet Mask 255.255.255.128 dengan 63 usable hosts"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Untuk prefix /25: sisa bit host = 32 - 25 = 7 bit. Usable hosts = 2^7 - 2 = 126 host, dengan Subnet Mask 255.255.255.128!", "explanation": "Prefix /25 memiliki 7 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^7 = 128 (255.255.255.128), dan jumlah host valid adalah 2^7 - 2 = 126 host."}, {"id": "SKB-PRAKOM-0172", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #172), ketika terjadi kondisi di mana: 'permintaan ditolak karena client belum menyertakan token autentikasi (seperti jwt/bearer token) yang valid', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 400 Bad Request", "B. 502 Bad Gateway", "C. 401 Unauthorized", "D. 500 Internal Server Error", "E. 200 OK"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 401 Unauthorized!", "explanation": "Kode status HTTP `401 Unauthorized` secara spesifik merepresentasikan kondisi: Permintaan ditolak karena client belum menyertakan token autentikasi (seperti JWT/Bearer Token) yang valid."}, {"id": "SKB-PRAKOM-0173", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Struktur Data & Algoritma", "q": "[Evaluasi Kompetensi Teknis Prakom #173] Berapakah kompleksitas waktu rata-rata (average time complexity) dari algoritma pencarian Binary Search pada sebuah array terurut berukuran $n$ elemen?", "options": ["A. O(1)", "B. O(log n)", "C. O(2^n)", "D. O(n²)", "E. O(n)"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Binary Search membagi dua ruang pencarian di setiap langkah pada data terurut, sehingga kompleksitas waktunya adalah logaritmik: O(log n).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Binary Search membagi dua ruang pencarian di setiap langkah pada data terurut, sehingga kompleksitas waktunya adalah logaritmik: O(log n)."}, {"id": "SKB-PRAKOM-0174", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #174:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.218.0/26`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/26` tersebut?", "options": ["A. Subnet Mask 255.255.255.192 dengan 31 usable hosts", "B. Subnet Mask 255.255.255.192 dengan 62 usable hosts (terbentuk 4 subnet dari blok /24)", "C. Subnet Mask 255.255.255.192 dengan 64 usable hosts", "D. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "E. Subnet Mask 255.255.255.0 dengan 124 usable hosts"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Untuk prefix /26: sisa bit host = 32 - 26 = 6 bit. Usable hosts = 2^6 - 2 = 62 host, dengan Subnet Mask 255.255.255.192!", "explanation": "Prefix /26 memiliki 6 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^6 = 192 (255.255.255.192), dan jumlah host valid adalah 2^6 - 2 = 62 host."}, {"id": "SKB-PRAKOM-0175", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #175), ketika terjadi kondisi di mana: 'client sudah terautentikasi, namun tidak memiliki hak akses (otorisasi/role) untuk mengakses endpoint tersebut', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 500 Internal Server Error", "B. 403 Forbidden", "C. 401 Unauthorized", "D. 400 Bad Request", "E. 502 Bad Gateway"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 403 Forbidden!", "explanation": "Kode status HTTP `403 Forbidden` secara spesifik merepresentasikan kondisi: Client sudah terautentikasi, namun tidak memiliki hak akses (otorisasi/role) untuk mengakses endpoint tersebut."}, {"id": "SKB-PRAKOM-0176", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Pemrograman Berorientasi Objek (OOP)", "q": "[Evaluasi Kompetensi Teknis Prakom #176] Prinsip dalam Object-Oriented Programming (OOP) yang membungkus atribut data dan metode di dalam satu unit kelas serta menyembunyikan detail internal menggunakan access modifier `private` disebut...", "options": ["A. Abstraction Interface", "B. Polymorphism (Polimorfisme)", "C. Inheritance (Pewarisan)", "D. Recursion (Rekursi)", "E. Encapsulation (Enkapsulasi)"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Empat pilar OOP: 1) Encapsulation (pembungkusan & penyembunyian data private), 2) Inheritance (pewarisan sifat superclass ke subclass), 3) Polymorphism (banyak bentuk method overriding/overloading), 4) Abstraction.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Empat pilar OOP: 1) Encapsulation (pembungkusan & penyembunyian data private), 2) Inheritance (pewarisan sifat superclass ke subclass), 3) Polymorphism (banyak bentuk method overriding/overloading), 4) Abstraction."}, {"id": "SKB-PRAKOM-0177", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #177:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.239.0/27`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/27` tersebut?", "options": ["A. Subnet Mask 255.255.255.224 dengan 15 usable hosts", "B. Subnet Mask 255.255.255.224 dengan 32 usable hosts", "C. Subnet Mask 255.255.255.224 dengan 30 usable hosts (terbentuk 8 subnet dari blok /24)", "D. Subnet Mask 255.255.255.0 dengan 60 usable hosts", "E. Subnet Mask 255.255.0.0 dengan 510 usable hosts"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Untuk prefix /27: sisa bit host = 32 - 27 = 5 bit. Usable hosts = 2^5 - 2 = 30 host, dengan Subnet Mask 255.255.255.224!", "explanation": "Prefix /27 memiliki 5 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^5 = 224 (255.255.255.224), dan jumlah host valid adalah 2^5 - 2 = 30 host."}, {"id": "SKB-PRAKOM-0178", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #178), ketika terjadi kondisi di mana: 'endpoint url atau resource data yang diminta client tidak ditemukan di dalam server', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 400 Bad Request", "B. 502 Bad Gateway", "C. 200 OK", "D. 500 Internal Server Error", "E. 404 Not Found"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 404 Not Found!", "explanation": "Kode status HTTP `404 Not Found` secara spesifik merepresentasikan kondisi: Endpoint URL atau resource data yang diminta client tidak ditemukan di dalam server."}, {"id": "SKB-PRAKOM-0179", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Infrastruktur Cloud Computing", "q": "[Evaluasi Kompetensi Teknis Prakom #179] Layanan komputasi awan (Cloud Computing) di mana penyedia cloud mengelola perangkat keras, jaringan, dan virtualisasi, sementara pengguna (Pranata Komputer) bertanggung jawab mengelola Sistem Operasi, Runtime, Middleware, dan Aplikasi (contoh: AWS EC2 / Google Compute Engine VM) adalah...", "options": ["A. IaaS (Infrastructure as a Service)", "B. On-Premise Bare Metal", "C. FaaS (Function as a Service)", "D. PaaS (Platform as a Service)", "E. SaaS (Software as a Service)"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Bedakan IaaS, PaaS, SaaS! IaaS = sewa VM/infrastruktur dasar (kita urus OS & aplikasi); PaaS = sewa platform siap coding (kita urus kode aplikasi & data saja); SaaS = aplikasi siap pakai (seperti Google Workspace / Microsoft 365).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Bedakan IaaS, PaaS, SaaS! IaaS = sewa VM/infrastruktur dasar (kita urus OS & aplikasi); PaaS = sewa platform siap coding (kita urus kode aplikasi & data saja); SaaS = aplikasi siap pakai (seperti Google Workspace / Microsoft 365)."}, {"id": "SKB-PRAKOM-0180", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #180:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.10.0/28`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/28` tersebut?", "options": ["A. Subnet Mask 255.255.255.0 dengan 28 usable hosts", "B. Subnet Mask 255.255.255.240 dengan 16 usable hosts", "C. Subnet Mask 255.255.255.240 dengan 14 usable hosts (terbentuk 16 subnet dari blok /24)", "D. Subnet Mask 255.255.255.240 dengan 7 usable hosts", "E. Subnet Mask 255.255.0.0 dengan 510 usable hosts"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Untuk prefix /28: sisa bit host = 32 - 28 = 4 bit. Usable hosts = 2^4 - 2 = 14 host, dengan Subnet Mask 255.255.255.240!", "explanation": "Prefix /28 memiliki 4 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^4 = 240 (255.255.255.240), dan jumlah host valid adalah 2^4 - 2 = 14 host."}, {"id": "SKB-PRAKOM-0181", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #181), ketika terjadi kondisi di mana: 'terjadi kesalahan tak terduga pada sisi kode atau layanan backend server saat memproses permintaan', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 200 OK", "B. 401 Unauthorized", "C. 500 Internal Server Error", "D. 404 Not Found", "E. 403 Forbidden"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 500 Internal Server Error!", "explanation": "Kode status HTTP `500 Internal Server Error` secara spesifik merepresentasikan kondisi: Terjadi kesalahan tak terduga pada sisi kode atau layanan backend server saat memproses permintaan."}, {"id": "SKB-PRAKOM-0182", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Protokol", "q": "[Evaluasi Kompetensi Teknis Prakom #182] Protokol jaringan yang bekerja secara otomatis mendistribusikan konfigurasi alamat IP, Subnet Mask, Default Gateway, dan DNS Server kepada komputer client di dalam jaringan lokal adalah...", "options": ["A. DHCP (Dynamic Host Configuration Protocol)", "B. ICMP (Internet Control Message Protocol)", "C. DNS (Domain Name System)", "D. SNMP (Simple Network Management Protocol)", "E. ARP (Address Resolution Protocol)"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "DHCP menggunakan proses DORA (Discover, Offer, Request, Acknowledge) untuk memberikan alamat IP secara otomatis ke host client.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: DHCP menggunakan proses DORA (Discover, Offer, Request, Acknowledge) untuk memberikan alamat IP secara otomatis ke host client."}, {"id": "SKB-PRAKOM-0183", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #183:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.31.0/29`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/29` tersebut?", "options": ["A. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "B. Subnet Mask 255.255.255.0 dengan 12 usable hosts", "C. Subnet Mask 255.255.255.248 dengan 8 usable hosts", "D. Subnet Mask 255.255.255.248 dengan 3 usable hosts", "E. Subnet Mask 255.255.255.248 dengan 6 usable hosts (terbentuk 32 subnet dari blok /24)"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Untuk prefix /29: sisa bit host = 32 - 29 = 3 bit. Usable hosts = 2^3 - 2 = 6 host, dengan Subnet Mask 255.255.255.248!", "explanation": "Prefix /29 memiliki 3 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^3 = 248 (255.255.255.248), dan jumlah host valid adalah 2^3 - 2 = 6 host."}, {"id": "SKB-PRAKOM-0184", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #184), ketika terjadi kondisi di mana: 'server yang bertindak sebagai reverse proxy atau api gateway menerima respons tidak valid dari server upstream', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 500 Internal Server Error", "B. 401 Unauthorized", "C. 502 Bad Gateway", "D. 200 OK", "E. 201 Created"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 502 Bad Gateway!", "explanation": "Kode status HTTP `502 Bad Gateway` secara spesifik merepresentasikan kondisi: Server yang bertindak sebagai reverse proxy atau API gateway menerima respons tidak valid dari server upstream."}, {"id": "SKB-PRAKOM-0185", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Port Standar", "q": "[Evaluasi Kompetensi Teknis Prakom #185] Pasangan protokol jaringan dan nomor port TCP/UDP standar berikut ini yang BENAR dalam administrasi server Linux/Windows adalah...", "options": ["A. SSH (Port 80), HTTPS (Port 21), DNS (Port 443), dan FTP (Port 22)", "B. SSH (Port 22), HTTPS (Port 443), DNS (Port 53), dan HTTP (Port 80)", "C. FTP (Port 53), SSH (Port 3306), dan PostgreSQL (Port 21)", "D. Telnet (Port 443), RDP (Port 25), dan HTTPS (Port 8080)", "E. SMTP (Port 80), POP3 (Port 22), dan MySQL (Port 53)"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Hafalkan Port Penting SKB Prakom: FTP=20/21, SSH=22, Telnet=23, SMTP=25, DNS=53, DHCP=67/68, HTTP=80, POP3=110, IMAP=143, HTTPS=443, MySQL=3306, RDP=3389, PostgreSQL=5432.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Hafalkan Port Penting SKB Prakom: FTP=20/21, SSH=22, Telnet=23, SMTP=25, DNS=53, DHCP=67/68, HTTP=80, POP3=110, IMAP=143, HTTPS=443, MySQL=3306, RDP=3389, PostgreSQL=5432."}, {"id": "SKB-PRAKOM-0186", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #186:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.52.0/30`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/30` tersebut?", "options": ["A. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "B. Subnet Mask 255.255.255.252 dengan 2 usable hosts", "C. Subnet Mask 255.255.255.0 dengan 4 usable hosts", "D. Subnet Mask 255.255.255.252 dengan 4 usable hosts", "E. Subnet Mask 255.255.255.252 dengan 2 usable hosts (terbentuk 64 subnet dari blok /24)"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Untuk prefix /30: sisa bit host = 32 - 30 = 2 bit. Usable hosts = 2^2 - 2 = 2 host, dengan Subnet Mask 255.255.255.252!", "explanation": "Prefix /30 memiliki 2 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^2 = 252 (255.255.255.252), dan jumlah host valid adalah 2^2 - 2 = 2 host."}, {"id": "SKB-PRAKOM-0187", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #187), ketika terjadi kondisi di mana: 'server sedang kelebihan beban (overload) atau sedang dalam masa pemeliharaan (maintenance) sementara', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 502 Bad Gateway", "B. 403 Forbidden", "C. 404 Not Found", "D. 500 Internal Server Error", "E. 503 Service Unavailable"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 503 Service Unavailable!", "explanation": "Kode status HTTP `503 Service Unavailable` secara spesifik merepresentasikan kondisi: Server sedang kelebihan beban (overload) atau sedang dalam masa pemeliharaan (maintenance) sementara."}, {"id": "SKB-PRAKOM-0188", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Audit TI & COBIT", "q": "[Evaluasi Kompetensi Teknis Prakom #188] Dalam pelaksanaan audit teknologi informasi pada instansi pemerintah, pemeriksaan terhadap pengendalian yang melekat pada aplikasi (seperti validasi input, pengendalian proses hitung, dan validasi output laporan) dikategorikan sebagai...", "options": ["A. Human Resource Administrative Control", "B. Environmental Control", "C. Application Control (Pengendalian Aplikasi)", "D. Physical Security Control", "E. IT General Control (Pengendalian Umum TI)"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Audit Sistem Informasi membagi pengendalian menjadi 2: 1) IT General Controls / ITGC (kebijakan keamanan umum, manajemen akses, backup, operasi pusat data), dan 2) Application Controls (Input Control, Processing Control, Output Control di dalam aplikasi).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Audit Sistem Informasi membagi pengendalian menjadi 2: 1) IT General Controls / ITGC (kebijakan keamanan umum, manajemen akses, backup, operasi pusat data), dan 2) Application Controls (Input Control, Processing Control, Output Control di dalam aplikasi)."}, {"id": "SKB-PRAKOM-0189", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #189:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.73.0/24`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/24` tersebut?", "options": ["A. Subnet Mask 255.255.255.0 dengan 256 usable hosts", "B. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "C. Subnet Mask 255.255.255.0 dengan 127 usable hosts", "D. Subnet Mask 255.255.255.0 dengan 508 usable hosts", "E. Subnet Mask 255.255.255.0 dengan 254 usable hosts (terbentuk 1 subnet dari blok /24)"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Untuk prefix /24: sisa bit host = 32 - 24 = 8 bit. Usable hosts = 2^8 - 2 = 254 host, dengan Subnet Mask 255.255.255.0!", "explanation": "Prefix /24 memiliki 8 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^8 = 0 (255.255.255.0), dan jumlah host valid adalah 2^8 - 2 = 254 host."}, {"id": "SKB-PRAKOM-0190", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #190), ketika terjadi kondisi di mana: 'permintaan http berhasil diproses secara normal oleh server rest api', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 404 Not Found", "B. 400 Bad Request", "C. 200 OK", "D. 502 Bad Gateway", "E. 500 Internal Server Error"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 200 OK!", "explanation": "Kode status HTTP `200 OK` secara spesifik merepresentasikan kondisi: Permintaan HTTP berhasil diproses secara normal oleh server REST API."}, {"id": "SKB-PRAKOM-0191", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Multimedia & Pengolahan Citra", "q": "[Evaluasi Kompetensi Teknis Prakom #191] Format file gambar grafis berbasis vektor standar web berbasis XML yang tidak mengalami pecah (blur/pixelated) meskipun diperbesar hingga skala berapa pun adalah...", "options": ["A. BMP (Bitmap Image)", "B. SVG (Scalable Vector Graphics)", "C. PNG (Portable Network Graphics)", "D. GIF (Graphics Interchange Format)", "E. JPEG (Joint Photographic Experts Group)"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Format Vektor = SVG, EPS, AI, CDR (berbasis rumus matematis titik/kurva, tidak pecah saat di-zoom). Format Raster/Bitmap = JPEG, PNG, GIF, BMP, WEBP.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Format Vektor = SVG, EPS, AI, CDR (berbasis rumus matematis titik/kurva, tidak pecah saat di-zoom). Format Raster/Bitmap = JPEG, PNG, GIF, BMP, WEBP."}, {"id": "SKB-PRAKOM-0192", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #192:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.94.0/25`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/25` tersebut?", "options": ["A. Subnet Mask 255.255.255.0 dengan 252 usable hosts", "B. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "C. Subnet Mask 255.255.255.128 dengan 128 usable hosts", "D. Subnet Mask 255.255.255.128 dengan 63 usable hosts", "E. Subnet Mask 255.255.255.128 dengan 126 usable hosts (terbentuk 2 subnet dari blok /24)"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Untuk prefix /25: sisa bit host = 32 - 25 = 7 bit. Usable hosts = 2^7 - 2 = 126 host, dengan Subnet Mask 255.255.255.128!", "explanation": "Prefix /25 memiliki 7 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^7 = 128 (255.255.255.128), dan jumlah host valid adalah 2^7 - 2 = 126 host."}, {"id": "SKB-PRAKOM-0193", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #193), ketika terjadi kondisi di mana: 'permintaan http post berhasil diproses dan sumber daya (resource) baru berhasil dibuat di server', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 503 Service Unavailable", "B. 404 Not Found", "C. 201 Created", "D. 403 Forbidden", "E. 400 Bad Request"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 201 Created!", "explanation": "Kode status HTTP `201 Created` secara spesifik merepresentasikan kondisi: Permintaan HTTP POST berhasil diproses dan sumber daya (resource) baru berhasil dibuat di server."}, {"id": "SKB-PRAKOM-0194", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Struktur Data & Algoritma", "q": "[Evaluasi Kompetensi Teknis Prakom #194] Struktur data linier yang menerapkan prinsip LIFO (Last In, First Out) di mana elemen yang terakhir dimasukkan adalah elemen pertama yang dikeluarkan (seperti fitur Undo pada editor teks) adalah...", "options": ["A. Stack (Tumpukan)", "B. Queue (Antrean - FIFO)", "C. Binary Search Tree", "D. Graph Berarah", "E. Hash Table"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "LIFO (Last In First Out) = Stack (operasi Push & Pop). FIFO (First In First Out) = Queue (operasi Enqueue & Dequeue).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: LIFO (Last In First Out) = Stack (operasi Push & Pop). FIFO (First In First Out) = Queue (operasi Enqueue & Dequeue)."}, {"id": "SKB-PRAKOM-0195", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #195:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.115.0/26`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/26` tersebut?", "options": ["A. Subnet Mask 255.255.255.0 dengan 124 usable hosts", "B. Subnet Mask 255.255.255.192 dengan 31 usable hosts", "C. Subnet Mask 255.255.255.192 dengan 62 usable hosts (terbentuk 4 subnet dari blok /24)", "D. Subnet Mask 255.255.255.192 dengan 64 usable hosts", "E. Subnet Mask 255.255.0.0 dengan 510 usable hosts"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Untuk prefix /26: sisa bit host = 32 - 26 = 6 bit. Usable hosts = 2^6 - 2 = 62 host, dengan Subnet Mask 255.255.255.192!", "explanation": "Prefix /26 memiliki 6 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^6 = 192 (255.255.255.192), dan jumlah host valid adalah 2^6 - 2 = 62 host."}, {"id": "SKB-PRAKOM-0196", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #196), ketika terjadi kondisi di mana: 'server tidak dapat memproses permintaan karena sintaks json atau parameter input dari client tidak valid', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 403 Forbidden", "B. 502 Bad Gateway", "C. 400 Bad Request", "D. 503 Service Unavailable", "E. 200 OK"], "ans": 2, "scores": [0, 0, 5, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 400 Bad Request!", "explanation": "Kode status HTTP `400 Bad Request` secara spesifik merepresentasikan kondisi: Server tidak dapat memproses permintaan karena sintaks JSON atau parameter input dari client tidak valid."}, {"id": "SKB-PRAKOM-0197", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Struktur Data & Algoritma", "q": "[Evaluasi Kompetensi Teknis Prakom #197] Berapakah kompleksitas waktu rata-rata (average time complexity) dari algoritma pencarian Binary Search pada sebuah array terurut berukuran $n$ elemen?", "options": ["A. O(2^n)", "B. O(n²)", "C. O(n)", "D. O(log n)", "E. O(1)"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Binary Search membagi dua ruang pencarian di setiap langkah pada data terurut, sehingga kompleksitas waktunya adalah logaritmik: O(log n).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Binary Search membagi dua ruang pencarian di setiap langkah pada data terurut, sehingga kompleksitas waktunya adalah logaritmik: O(log n)."}, {"id": "SKB-PRAKOM-0198", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #198:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.136.0/27`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/27` tersebut?", "options": ["A. Subnet Mask 255.255.255.224 dengan 32 usable hosts", "B. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "C. Subnet Mask 255.255.255.0 dengan 60 usable hosts", "D. Subnet Mask 255.255.255.224 dengan 30 usable hosts (terbentuk 8 subnet dari blok /24)", "E. Subnet Mask 255.255.255.224 dengan 15 usable hosts"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Untuk prefix /27: sisa bit host = 32 - 27 = 5 bit. Usable hosts = 2^5 - 2 = 30 host, dengan Subnet Mask 255.255.255.224!", "explanation": "Prefix /27 memiliki 5 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^5 = 224 (255.255.255.224), dan jumlah host valid adalah 2^5 - 2 = 30 host."}, {"id": "SKB-PRAKOM-0199", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #199), ketika terjadi kondisi di mana: 'permintaan ditolak karena client belum menyertakan token autentikasi (seperti jwt/bearer token) yang valid', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 403 Forbidden", "B. 401 Unauthorized", "C. 404 Not Found", "D. 400 Bad Request", "E. 201 Created"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 401 Unauthorized!", "explanation": "Kode status HTTP `401 Unauthorized` secara spesifik merepresentasikan kondisi: Permintaan ditolak karena client belum menyertakan token autentikasi (seperti JWT/Bearer Token) yang valid."}, {"id": "SKB-PRAKOM-0200", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Pemrograman Berorientasi Objek (OOP)", "q": "[Evaluasi Kompetensi Teknis Prakom #200] Prinsip dalam Object-Oriented Programming (OOP) yang membungkus atribut data dan metode di dalam satu unit kelas serta menyembunyikan detail internal menggunakan access modifier `private` disebut...", "options": ["A. Encapsulation (Enkapsulasi)", "B. Inheritance (Pewarisan)", "C. Abstraction Interface", "D. Recursion (Rekursi)", "E. Polymorphism (Polimorfisme)"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Empat pilar OOP: 1) Encapsulation (pembungkusan & penyembunyian data private), 2) Inheritance (pewarisan sifat superclass ke subclass), 3) Polymorphism (banyak bentuk method overriding/overloading), 4) Abstraction.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Empat pilar OOP: 1) Encapsulation (pembungkusan & penyembunyian data private), 2) Inheritance (pewarisan sifat superclass ke subclass), 3) Polymorphism (banyak bentuk method overriding/overloading), 4) Abstraction."}, {"id": "SKB-PRAKOM-0201", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #201:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.157.0/28`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/28` tersebut?", "options": ["A. Subnet Mask 255.255.255.0 dengan 28 usable hosts", "B. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "C. Subnet Mask 255.255.255.240 dengan 16 usable hosts", "D. Subnet Mask 255.255.255.240 dengan 14 usable hosts (terbentuk 16 subnet dari blok /24)", "E. Subnet Mask 255.255.255.240 dengan 7 usable hosts"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Untuk prefix /28: sisa bit host = 32 - 28 = 4 bit. Usable hosts = 2^4 - 2 = 14 host, dengan Subnet Mask 255.255.255.240!", "explanation": "Prefix /28 memiliki 4 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^4 = 240 (255.255.255.240), dan jumlah host valid adalah 2^4 - 2 = 14 host."}, {"id": "SKB-PRAKOM-0202", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #202), ketika terjadi kondisi di mana: 'client sudah terautentikasi, namun tidak memiliki hak akses (otorisasi/role) untuk mengakses endpoint tersebut', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 403 Forbidden", "B. 400 Bad Request", "C. 200 OK", "D. 404 Not Found", "E. 401 Unauthorized"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 403 Forbidden!", "explanation": "Kode status HTTP `403 Forbidden` secara spesifik merepresentasikan kondisi: Client sudah terautentikasi, namun tidak memiliki hak akses (otorisasi/role) untuk mengakses endpoint tersebut."}, {"id": "SKB-PRAKOM-0203", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Infrastruktur Cloud Computing", "q": "[Evaluasi Kompetensi Teknis Prakom #203] Layanan komputasi awan (Cloud Computing) di mana penyedia cloud mengelola perangkat keras, jaringan, dan virtualisasi, sementara pengguna (Pranata Komputer) bertanggung jawab mengelola Sistem Operasi, Runtime, Middleware, dan Aplikasi (contoh: AWS EC2 / Google Compute Engine VM) adalah...", "options": ["A. PaaS (Platform as a Service)", "B. IaaS (Infrastructure as a Service)", "C. FaaS (Function as a Service)", "D. SaaS (Software as a Service)", "E. On-Premise Bare Metal"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Bedakan IaaS, PaaS, SaaS! IaaS = sewa VM/infrastruktur dasar (kita urus OS & aplikasi); PaaS = sewa platform siap coding (kita urus kode aplikasi & data saja); SaaS = aplikasi siap pakai (seperti Google Workspace / Microsoft 365).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Bedakan IaaS, PaaS, SaaS! IaaS = sewa VM/infrastruktur dasar (kita urus OS & aplikasi); PaaS = sewa platform siap coding (kita urus kode aplikasi & data saja); SaaS = aplikasi siap pakai (seperti Google Workspace / Microsoft 365)."}, {"id": "SKB-PRAKOM-0204", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #204:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.178.0/29`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/29` tersebut?", "options": ["A. Subnet Mask 255.255.255.248 dengan 3 usable hosts", "B. Subnet Mask 255.255.255.248 dengan 6 usable hosts (terbentuk 32 subnet dari blok /24)", "C. Subnet Mask 255.255.255.248 dengan 8 usable hosts", "D. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "E. Subnet Mask 255.255.255.0 dengan 12 usable hosts"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Untuk prefix /29: sisa bit host = 32 - 29 = 3 bit. Usable hosts = 2^3 - 2 = 6 host, dengan Subnet Mask 255.255.255.248!", "explanation": "Prefix /29 memiliki 3 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^3 = 248 (255.255.255.248), dan jumlah host valid adalah 2^3 - 2 = 6 host."}, {"id": "SKB-PRAKOM-0205", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #205), ketika terjadi kondisi di mana: 'endpoint url atau resource data yang diminta client tidak ditemukan di dalam server', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 503 Service Unavailable", "B. 403 Forbidden", "C. 200 OK", "D. 400 Bad Request", "E. 404 Not Found"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 404 Not Found!", "explanation": "Kode status HTTP `404 Not Found` secara spesifik merepresentasikan kondisi: Endpoint URL atau resource data yang diminta client tidak ditemukan di dalam server."}, {"id": "SKB-PRAKOM-0206", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Protokol", "q": "[Evaluasi Kompetensi Teknis Prakom #206] Protokol jaringan yang bekerja secara otomatis mendistribusikan konfigurasi alamat IP, Subnet Mask, Default Gateway, dan DNS Server kepada komputer client di dalam jaringan lokal adalah...", "options": ["A. SNMP (Simple Network Management Protocol)", "B. DNS (Domain Name System)", "C. ICMP (Internet Control Message Protocol)", "D. ARP (Address Resolution Protocol)", "E. DHCP (Dynamic Host Configuration Protocol)"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "DHCP menggunakan proses DORA (Discover, Offer, Request, Acknowledge) untuk memberikan alamat IP secara otomatis ke host client.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: DHCP menggunakan proses DORA (Discover, Offer, Request, Acknowledge) untuk memberikan alamat IP secara otomatis ke host client."}, {"id": "SKB-PRAKOM-0207", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #207:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.199.0/30`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/30` tersebut?", "options": ["A. Subnet Mask 255.255.255.252 dengan 2 usable hosts (terbentuk 64 subnet dari blok /24)", "B. Subnet Mask 255.255.255.252 dengan 4 usable hosts", "C. Subnet Mask 255.255.255.252 dengan 2 usable hosts", "D. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "E. Subnet Mask 255.255.255.0 dengan 4 usable hosts"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Untuk prefix /30: sisa bit host = 32 - 30 = 2 bit. Usable hosts = 2^2 - 2 = 2 host, dengan Subnet Mask 255.255.255.252!", "explanation": "Prefix /30 memiliki 2 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^2 = 252 (255.255.255.252), dan jumlah host valid adalah 2^2 - 2 = 2 host."}, {"id": "SKB-PRAKOM-0208", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #208), ketika terjadi kondisi di mana: 'terjadi kesalahan tak terduga pada sisi kode atau layanan backend server saat memproses permintaan', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 401 Unauthorized", "B. 502 Bad Gateway", "C. 503 Service Unavailable", "D. 500 Internal Server Error", "E. 400 Bad Request"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 500 Internal Server Error!", "explanation": "Kode status HTTP `500 Internal Server Error` secara spesifik merepresentasikan kondisi: Terjadi kesalahan tak terduga pada sisi kode atau layanan backend server saat memproses permintaan."}, {"id": "SKB-PRAKOM-0209", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Port Standar", "q": "[Evaluasi Kompetensi Teknis Prakom #209] Pasangan protokol jaringan dan nomor port TCP/UDP standar berikut ini yang BENAR dalam administrasi server Linux/Windows adalah...", "options": ["A. Telnet (Port 443), RDP (Port 25), dan HTTPS (Port 8080)", "B. FTP (Port 53), SSH (Port 3306), dan PostgreSQL (Port 21)", "C. SSH (Port 80), HTTPS (Port 21), DNS (Port 443), dan FTP (Port 22)", "D. SSH (Port 22), HTTPS (Port 443), DNS (Port 53), dan HTTP (Port 80)", "E. SMTP (Port 80), POP3 (Port 22), dan MySQL (Port 53)"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Hafalkan Port Penting SKB Prakom: FTP=20/21, SSH=22, Telnet=23, SMTP=25, DNS=53, DHCP=67/68, HTTP=80, POP3=110, IMAP=143, HTTPS=443, MySQL=3306, RDP=3389, PostgreSQL=5432.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Hafalkan Port Penting SKB Prakom: FTP=20/21, SSH=22, Telnet=23, SMTP=25, DNS=53, DHCP=67/68, HTTP=80, POP3=110, IMAP=143, HTTPS=443, MySQL=3306, RDP=3389, PostgreSQL=5432."}, {"id": "SKB-PRAKOM-0210", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #210:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.220.0/24`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/24` tersebut?", "options": ["A. Subnet Mask 255.255.255.0 dengan 254 usable hosts (terbentuk 1 subnet dari blok /24)", "B. Subnet Mask 255.255.255.0 dengan 256 usable hosts", "C. Subnet Mask 255.255.255.0 dengan 127 usable hosts", "D. Subnet Mask 255.255.255.0 dengan 508 usable hosts", "E. Subnet Mask 255.255.0.0 dengan 510 usable hosts"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Untuk prefix /24: sisa bit host = 32 - 24 = 8 bit. Usable hosts = 2^8 - 2 = 254 host, dengan Subnet Mask 255.255.255.0!", "explanation": "Prefix /24 memiliki 8 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^8 = 0 (255.255.255.0), dan jumlah host valid adalah 2^8 - 2 = 254 host."}, {"id": "SKB-PRAKOM-0211", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #211), ketika terjadi kondisi di mana: 'server yang bertindak sebagai reverse proxy atau api gateway menerima respons tidak valid dari server upstream', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 503 Service Unavailable", "B. 401 Unauthorized", "C. 200 OK", "D. 502 Bad Gateway", "E. 201 Created"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 502 Bad Gateway!", "explanation": "Kode status HTTP `502 Bad Gateway` secara spesifik merepresentasikan kondisi: Server yang bertindak sebagai reverse proxy atau API gateway menerima respons tidak valid dari server upstream."}, {"id": "SKB-PRAKOM-0212", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Audit TI & COBIT", "q": "[Evaluasi Kompetensi Teknis Prakom #212] Dalam pelaksanaan audit teknologi informasi pada instansi pemerintah, pemeriksaan terhadap pengendalian yang melekat pada aplikasi (seperti validasi input, pengendalian proses hitung, dan validasi output laporan) dikategorikan sebagai...", "options": ["A. Physical Security Control", "B. Environmental Control", "C. IT General Control (Pengendalian Umum TI)", "D. Application Control (Pengendalian Aplikasi)", "E. Human Resource Administrative Control"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Audit Sistem Informasi membagi pengendalian menjadi 2: 1) IT General Controls / ITGC (kebijakan keamanan umum, manajemen akses, backup, operasi pusat data), dan 2) Application Controls (Input Control, Processing Control, Output Control di dalam aplikasi).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Audit Sistem Informasi membagi pengendalian menjadi 2: 1) IT General Controls / ITGC (kebijakan keamanan umum, manajemen akses, backup, operasi pusat data), dan 2) Application Controls (Input Control, Processing Control, Output Control di dalam aplikasi)."}, {"id": "SKB-PRAKOM-0213", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #213:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.241.0/25`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/25` tersebut?", "options": ["A. Subnet Mask 255.255.255.128 dengan 128 usable hosts", "B. Subnet Mask 255.255.255.128 dengan 63 usable hosts", "C. Subnet Mask 255.255.255.0 dengan 252 usable hosts", "D. Subnet Mask 255.255.255.128 dengan 126 usable hosts (terbentuk 2 subnet dari blok /24)", "E. Subnet Mask 255.255.0.0 dengan 510 usable hosts"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Untuk prefix /25: sisa bit host = 32 - 25 = 7 bit. Usable hosts = 2^7 - 2 = 126 host, dengan Subnet Mask 255.255.255.128!", "explanation": "Prefix /25 memiliki 7 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^7 = 128 (255.255.255.128), dan jumlah host valid adalah 2^7 - 2 = 126 host."}, {"id": "SKB-PRAKOM-0214", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #214), ketika terjadi kondisi di mana: 'server sedang kelebihan beban (overload) atau sedang dalam masa pemeliharaan (maintenance) sementara', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 403 Forbidden", "B. 201 Created", "C. 200 OK", "D. 503 Service Unavailable", "E. 404 Not Found"], "ans": 3, "scores": [0, 0, 0, 5, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 503 Service Unavailable!", "explanation": "Kode status HTTP `503 Service Unavailable` secara spesifik merepresentasikan kondisi: Server sedang kelebihan beban (overload) atau sedang dalam masa pemeliharaan (maintenance) sementara."}, {"id": "SKB-PRAKOM-0215", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Multimedia & Pengolahan Citra", "q": "[Evaluasi Kompetensi Teknis Prakom #215] Format file gambar grafis berbasis vektor standar web berbasis XML yang tidak mengalami pecah (blur/pixelated) meskipun diperbesar hingga skala berapa pun adalah...", "options": ["A. GIF (Graphics Interchange Format)", "B. PNG (Portable Network Graphics)", "C. JPEG (Joint Photographic Experts Group)", "D. BMP (Bitmap Image)", "E. SVG (Scalable Vector Graphics)"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Format Vektor = SVG, EPS, AI, CDR (berbasis rumus matematis titik/kurva, tidak pecah saat di-zoom). Format Raster/Bitmap = JPEG, PNG, GIF, BMP, WEBP.", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: Format Vektor = SVG, EPS, AI, CDR (berbasis rumus matematis titik/kurva, tidak pecah saat di-zoom). Format Raster/Bitmap = JPEG, PNG, GIF, BMP, WEBP."}, {"id": "SKB-PRAKOM-0216", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #216:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.12.0/26`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/26` tersebut?", "options": ["A. Subnet Mask 255.255.255.192 dengan 62 usable hosts (terbentuk 4 subnet dari blok /24)", "B. Subnet Mask 255.255.255.0 dengan 124 usable hosts", "C. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "D. Subnet Mask 255.255.255.192 dengan 64 usable hosts", "E. Subnet Mask 255.255.255.192 dengan 31 usable hosts"], "ans": 0, "scores": [5, 0, 0, 0, 0], "trick": "Untuk prefix /26: sisa bit host = 32 - 26 = 6 bit. Usable hosts = 2^6 - 2 = 62 host, dengan Subnet Mask 255.255.255.192!", "explanation": "Prefix /26 memiliki 6 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^6 = 192 (255.255.255.192), dan jumlah host valid adalah 2^6 - 2 = 62 host."}, {"id": "SKB-PRAKOM-0217", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #217), ketika terjadi kondisi di mana: 'permintaan http berhasil diproses secara normal oleh server rest api', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 403 Forbidden", "B. 404 Not Found", "C. 503 Service Unavailable", "D. 401 Unauthorized", "E. 200 OK"], "ans": 4, "scores": [0, 0, 0, 0, 5], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 200 OK!", "explanation": "Kode status HTTP `200 OK` secara spesifik merepresentasikan kondisi: Permintaan HTTP berhasil diproses secara normal oleh server REST API."}, {"id": "SKB-PRAKOM-0218", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Struktur Data & Algoritma", "q": "[Evaluasi Kompetensi Teknis Prakom #218] Struktur data linier yang menerapkan prinsip LIFO (Last In, First Out) di mana elemen yang terakhir dimasukkan adalah elemen pertama yang dikeluarkan (seperti fitur Undo pada editor teks) adalah...", "options": ["A. Graph Berarah", "B. Stack (Tumpukan)", "C. Queue (Antrean - FIFO)", "D. Hash Table", "E. Binary Search Tree"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "LIFO (Last In First Out) = Stack (operasi Push & Pop). FIFO (First In First Out) = Queue (operasi Enqueue & Dequeue).", "explanation": "Sesuai standar kompetensi teknis Jabatan Fungsional Pranata Komputer: LIFO (Last In First Out) = Stack (operasi Push & Pop). FIFO (First In First Out) = Queue (operasi Enqueue & Dequeue)."}, {"id": "SKB-PRAKOM-0219", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Jaringan Komputer & Subnetting", "q": "Studi Kasus Jaringan Pemerintah #219:\nSeorang Pranata Komputer merancang jaringan VLAN gedung kantor dengan blok alamat IP `192.168.33.0/27`. Berapakah Subnet Mask desimal dan jumlah maksimal host aktif (usable hosts) per subnet pada konfigurasi `/27` tersebut?", "options": ["A. Subnet Mask 255.255.255.224 dengan 15 usable hosts", "B. Subnet Mask 255.255.255.224 dengan 30 usable hosts (terbentuk 8 subnet dari blok /24)", "C. Subnet Mask 255.255.255.224 dengan 32 usable hosts", "D. Subnet Mask 255.255.0.0 dengan 510 usable hosts", "E. Subnet Mask 255.255.255.0 dengan 60 usable hosts"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Untuk prefix /27: sisa bit host = 32 - 27 = 5 bit. Usable hosts = 2^5 - 2 = 30 host, dengan Subnet Mask 255.255.255.224!", "explanation": "Prefix /27 memiliki 5 bit host. Nilai oktet terakhir subnet mask adalah 256 - 2^5 = 224 (255.255.255.224), dan jumlah host valid adalah 2^5 - 2 = 30 host."}, {"id": "SKB-PRAKOM-0220", "examType": "SKB_PRAKOM", "category": "SKB PRANATA KOMPUTER", "sub": "Rekayasa Perangkat Lunak & Integrasi API", "q": "Dalam integrasi layanan Web Service / RESTful API antar-instansi dalam kerangka SPBE (Kasus Integrasi #220), ketika terjadi kondisi di mana: 'permintaan http post berhasil diproses dan sumber daya (resource) baru berhasil dibuat di server', kode status HTTP standar yang dikembalikan oleh server adalah...", "options": ["A. 404 Not Found", "B. 201 Created", "C. 500 Internal Server Error", "D. 403 Forbidden", "E. 400 Bad Request"], "ans": 1, "scores": [0, 5, 0, 0, 0], "trick": "Hafalkan kelompok kode HTTP: 2xx = Sukses, 4xx = Kesalahan Client (400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found), 5xx = Kesalahan Server -> 201 Created!", "explanation": "Kode status HTTP `201 Created` secara spesifik merepresentasikan kondisi: Permintaan HTTP POST berhasil diproses dan sumber daya (resource) baru berhasil dibuat di server."}]});
